(function() {
  function syncThemeColor() {
    var isLight = document.body.classList.contains('light-mode');
    var navBg = isLight ? '#F0EEE9' : '#09090b';
    var meta = document.querySelector('meta[name="theme-color"]');
    if (meta) meta.setAttribute('content', navBg);
    document.documentElement.style.backgroundColor = navBg;
  }
  /* Read the base the pre-paint block already resolved; do not resolve it
     again. This used to read zw_theme_mode with its own 'super-light' default
     and ADD the classes — never remove them — so a dark theme could not undo
     it and the page kept light-mode rules over dark tokens. toggle() from the
     one answer means it agrees by construction. */
  try { var _zb=document.documentElement.getAttribute('data-zw-base')||'dark';
        document.body.classList.toggle('light-mode',_zb!=='dark');
        document.body.classList.toggle('super-light-mode',_zb==='super-light'); } catch(_) {}
  syncThemeColor();
  window.__zwSyncThemeColor = syncThemeColor;
})();

