// _sessionPromise.then() moved into startWithSb() so it runs after the promise is created

document.addEventListener('DOMContentLoaded', async () => {
  const bar = document.getElementById('bar');
  const nav = document.querySelector('.nav');
  if (bar && nav) {
    // The bar is display:none until the async site-setting resolves, and the CSS
    // padding-top (140px, desktop-sized) reserves space for it — leaving a tall
    // white gap above the product on slow loads. Clear it to just the nav height
    // now; loadSiteSettings re-applies with the real bar state/height.
    const syncNavOffset = () => {
      if (window.matchMedia('(max-width: 900px)').matches) {
        nav.style.top = '0';
        document.documentElement.style.setProperty('--mobile-nav-gap', '0px');
        return;
      }
      const isHidden = bar.style.display === 'none' || bar.style.opacity === '0' || bar.style.pointerEvents === 'none';
      nav.style.top = isHidden ? '0' : (bar.offsetHeight + 'px');
    };
    syncNavOffset();
    window.addEventListener('resize', syncNavOffset);
  }

  loadCartCount();
  try {
    // Wait for startWithSb() to run and kick off the product fetch.
    // _sbReady resolves the moment startWithSb sets _productFetchPromise,
    // eliminating the previous fragile setTimeout(0) poll.
    await _sbReady;
    if (_productFetchPromise) await _productFetchPromise;
    renderProduct();
  } catch (err) {
    console.error('Product load error:', err);
    showError(err.message || 'Failed to load product');
  }
});

