function ensureProductImageFallback(images, product) {
  const list = Array.isArray(images) ? [...images] : [];
  if (product?.image_url && !list.some(img => img?.image_url === product.image_url)) {
    list.unshift({ image_url: product.image_url, alt_text: product.title });
  }
  if (!list.length && product?.image_url) {
    list.push({ image_url: product.image_url, alt_text: product.title });
  }
  return list;
}

async function loadProduct() {
  const params = new URLSearchParams(window.location.search);
  const productId = params.get('id');
  const sku = params.get('sku');
  let slug = params.get('slug');
  // Variant deep-link — preselect this colour/size once the product renders.
  if (params.get('color')) _pendingColor = params.get('color');
  if (params.get('size')) _pendingSize = params.get('size');

  // Fallback: extract slug from pathname for clean URLs (e.g. /product/vogue)
  if (!productId && !sku && !slug) {
    const pathParts = window.location.pathname.replace(/^\//, '').replace(/\/$/, '').split('/');
    if (pathParts.length === 2 && pathParts[0] === 'product' && pathParts[1]) {
      slug = pathParts[1];
    } else if (pathParts.length === 1 && pathParts[0] && pathParts[0] !== 'product.html' && pathParts[0] !== 'product') {
      slug = pathParts[0];
    }
  }

  // Fetch the product first, then related tables separately by product_id so gallery data
  // never bleeds across products if an embedded relationship returns unexpected rows.
  const headers = { 'apikey': _PROD_SB_KEY, 'Authorization': `Bearer ${_PROD_SB_KEY}` };

  let productData = null;
  if (productId) {
    const resp = await fetch(`${_PROD_SB_URL}/rest/v1/products?select=*&id=eq.${encodeURIComponent(productId)}&limit=1`, { headers, cache: 'no-store' });
    if (!resp.ok) throw new Error('Product not found');
    const data = await resp.json();
    productData = data ? data[0] : null;
  } else if (sku) {
    const resp = await fetch(`${_PROD_SB_URL}/rest/v1/products?select=*&sku=eq.${encodeURIComponent(sku)}&limit=1`, { headers, cache: 'no-store' });
    if (!resp.ok) throw new Error('Product not found');
    const data = await resp.json();
    productData = data ? data[0] : null;
  } else if (slug) {
    const resp = await fetch(`${_PROD_SB_URL}/rest/v1/products?select=*&status=neq.Legacy&status=neq.Draft&order=sort_order.asc`, { headers, cache: 'no-store' });
    if (!resp.ok) throw new Error('Product not found');
    const data = await resp.json();
    const products = Array.isArray(data) ? data : [];
    productData = pickProductBySlug(products, slug);

    if (!productData) {
      const searchSlug = slug.replace(/-/g, '*');
      const fallbackResp = await fetch(`${_PROD_SB_URL}/rest/v1/products?select=*&status=neq.Legacy&status=neq.Draft&title=ilike.*${encodeURIComponent(searchSlug)}*&order=sort_order.asc&limit=5`, { headers });
      if (fallbackResp.ok) {
        const fallbackData = await fallbackResp.json();
        const fallbackProducts = Array.isArray(fallbackData) ? fallbackData : [];
        productData = pickProductBySlug(fallbackProducts, slug) || fallbackProducts[0] || null;
      }
    }
  } else {
    const resp = await fetch(`${_PROD_SB_URL}/rest/v1/products?select=*&status=eq.Live&order=sort_order.asc&limit=1`, { headers });
    if (!resp.ok) throw new Error('Product not found');
    const data = await resp.json();
    productData = data ? data[0] : null;
  }

  if (!productData) {
    throw new Error('Product not found');
  }

  if ((productData.status || '').toLowerCase() === 'legacy' || (productData.status || '').toLowerCase() === 'draft') {
    window.location.replace('/404');
    return;
  }

  const resolvedSlug = normalizedProductSlug(productData.slug || productData.title || productData.name);
  const resolvedParams = new URLSearchParams();
  resolvedParams.set('id', productData.id);
  if (productData.sku) resolvedParams.set('sku', productData.sku);
  // Keep the variant deep-link in the canonical URL so it survives + is shareable.
  if (_pendingColor) resolvedParams.set('color', _pendingColor);
  if (_pendingSize) resolvedParams.set('size', _pendingSize);
  const resolvedPath = resolvedSlug ? `/product/${resolvedSlug}` : '/product';
  const resolvedUrl = `${resolvedPath}?${resolvedParams.toString()}`;
  if (`${window.location.pathname}${window.location.search}` !== resolvedUrl) {
    window.history.replaceState({}, '', resolvedUrl);
  }

  const productIdFilter = encodeURIComponent(productData.id);
  const imagesPromise = fetch(`${_PROD_SB_URL}/rest/v1/product_images?select=*&product_id=eq.${productIdFilter}&order=sort_order.asc`, { headers })
    .then((imagesResp) => imagesResp.ok ? imagesResp.json() : [])
    .catch((error) => {
      console.warn('Image gallery load fallback:', error);
      return [];
    });
  const reviewsPromise = fetch(`${_PROD_SB_URL}/rest/v1/reviews?select=*&product_id=eq.${productIdFilter}&order=created_at.desc`, { headers })
    .then((reviewsResp) => reviewsResp.ok ? reviewsResp.json() : [])
    .catch((error) => {
      console.warn('Review load fallback:', error);
      return [];
    });
  const [colorsResp, sizesResp] = await Promise.all([
    // no-store: stock/variant availability must be live — never a cached "previous" value
    fetch(`${_PROD_SB_URL}/rest/v1/color_variants?select=*&product_id=eq.${productIdFilter}&order=sort_order.asc`, { headers, cache: 'no-store' }),
    fetch(`${_PROD_SB_URL}/rest/v1/product_sizes?select=*&product_id=eq.${productIdFilter}`, { headers, cache: 'no-store' }),
  ]);
  const colorsData = colorsResp.ok ? await colorsResp.json() : [];
  const sizesData = sizesResp.ok ? await sizesResp.json() : [];

  // Normalize field names
  if (!productData.title && productData.name) productData.title = productData.name;
  if (!productData.current_price && productData.price) productData.current_price = parseFloat(productData.price) || 0;
  if (!productData.subtitle && productData.category) productData.subtitle = productData.category;
  if (!productData.gender && productData.subtitle) productData.gender = productData.subtitle;

  // Extract embedded arrays and sort client-side
  const strictProductId = String(productData.id);
  const colors = (Array.isArray(colorsData) ? colorsData : [])
    .filter((color) => String(color?.product_id) === strictProductId)
    .sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0));
  const inventory = giftCardInventory(productData, sizesData, strictProductId);

  currentProduct          = productData;
  currentProduct.images   = ensureProductImageFallback([], productData);
  currentProduct.colors   = colors;
  currentProduct.inventory = inventory;
  currentProduct.reviews  = [];
  // Announce the loaded product to opt-in storefront features (storefront-features.js:
  // recently-viewed + recommendations). Guarded so it never affects the PDP itself.
  try {
    window.__zwCurrentProduct = currentProduct;
    window.dispatchEvent(new CustomEvent('zw-product-loaded', { detail: currentProduct }));
  } catch (_) {}
  imagesPromise.then((imagesData) => {
    if (!currentProduct || String(currentProduct.id) !== strictProductId) return;
    const seenImageUrls = new Set();
    const images = (Array.isArray(imagesData) ? imagesData : [])
      .filter((image) => String(image?.product_id) === strictProductId && image?.image_url)
      .sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0))
      .filter((image) => {
        if (seenImageUrls.has(image.image_url)) return false;
        seenImageUrls.add(image.image_url);
        return true;
      });
    // Store all images; filter by selected color (or show shared if no color)
    currentProduct.allImages = ensureProductImageFallback(images, currentProduct);
    currentProduct.images = getImagesForColor(selectedColor?.id || null);
    currentImageIndex = Math.min(currentImageIndex, Math.max(currentProduct.images.length - 1, 0));
    renderGallery();
    updateColorwayThumbnails();
    syncProductSaveButton();
  });
  reviewsPromise.then((reviewsData) => {
    if (!currentProduct || String(currentProduct.id) !== strictProductId) return;
    currentProduct.reviews = (Array.isArray(reviewsData) ? reviewsData : [])
      .filter((review) => String(review?.product_id) === strictProductId);
    renderReviews();
  });
}

// ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â
// RENDER PRODUCT
// ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â
function renderProduct() {
  if (!currentProduct) return;

  document.getElementById('loadingState').classList.add('hidden');
  document.getElementById('productContainer').classList.remove('hidden');

  // Track product view
  zwTrack('product_viewed', {
    product_id:   currentProduct.id,
    product_name: currentProduct.title,
    price:        getEffectiveProductPrice(currentProduct),
    category:     currentProduct.gender || '',
    sku:          currentProduct.sku    || '',
  });
  if (window.zwPixel) zwPixel.viewContent({
    id:    currentProduct.id,
    title: currentProduct.title,
    price: getEffectiveProductPrice(currentProduct)
  });

  // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Product Header ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
  document.getElementById('productTitle').textContent = currentProduct.title;
  const _mi = document.getElementById('mainImage');
  if (_mi && !_mi.alt && currentProduct.title) _mi.alt = currentProduct.title;
  // Descriptive line under the title ("says what it is", like Nike). Use the
  // admin's custom `descriptor` override when set, else auto-build "<Gender>'s
  // <Category>" from gender + subtitle (the category). CSS uppercases it, so the
  // stored casing can stay natural. Mirrors the live preview in admin-main.js.
  {
    // Singularise the category where it reads better ("Jacket" not "Jackets"),
    // but keep plural-only / pair garments (Pants, Shorts, Leggings, Socks…) as-is.
    window.zwSingularCat = window.zwSingularCat || function (c) {
      if (!c) return c;
      var s = String(c).trim();
      if (/(pants|shorts|leggings|joggers|socks|jeans|tights|briefs|boxers|trousers|sunglasses|glasses|shoes|sneakers|boots|sandals|slides|gloves|overalls|pajamas|pyjamas)$/i.test(s)) return s;
      return /[^s]s$/i.test(s) ? s.slice(0, -1) : s;
    };
    const _g = (currentProduct.gender || '').trim();
    const _cat = window.zwSingularCat((currentProduct.subtitle || '').trim());
    const _poss = _g === 'Men' ? "Men's" : _g === 'Women' ? "Women's" : _g === 'Kids' ? "Kids'" : (_g || '');
    const _custom = (currentProduct.descriptor || '').trim();
    /* "Unisex Gift Card" is the gender line doing its job on something with no
       gender. A gift card is not men's or women's, it is a gift card — and the
       auto-build is Gender + Category precisely because every OTHER product
       needs both halves to read correctly. */
    const _isCard = Number(currentProduct.gift_card_cents) > 0;
    const _desc = _custom
      || (_isCard ? 'Gift Card'
        : ((_poss && _cat) ? (_poss + ' ' + _cat) : (_poss || _cat || 'All')));
    document.getElementById('genderTag').textContent = _desc;
  }

  applyGiftCardPageType();
  renderProductCategoryNavigation(currentProduct).catch((error) => console.warn('Failed to render category navigation:', error));

  // Dynamic SEO meta — update page title and social tags per product
  const _pTitle = currentProduct.title ? `${currentProduct.title} — ZUWERA` : 'Product — ZUWERA';
  const _pDesc  = currentProduct.description || `Shop ${currentProduct.title} at ZUWERA.`;
  const _pUrl   = `https://zuwera.store/product.html?id=${encodeURIComponent(currentProduct.id || '')}`;
  const _pImg   = currentProduct.image_url || 'https://zuwera.store/images/og-image.jpg';
  document.title = _pTitle;
  const _setMeta = (sel, content) => { const el = document.querySelector(sel); if (el) el.setAttribute('content', content); };
  _setMeta('meta[name="description"]',        _pDesc);
  _setMeta('meta[property="og:title"]',       _pTitle);
  _setMeta('meta[property="og:description"]', _pDesc);
  _setMeta('meta[property="og:url"]',         _pUrl);
  _setMeta('meta[property="og:image"]',       _pImg);
  const _canon = document.querySelector('link[rel="canonical"]');
  if (_canon) _canon.setAttribute('href', _pUrl);

  // Inject Product JSON-LD structured data for Google Shopping / rich results
  const _price = currentProduct.current_price || currentProduct.msrp || '';
  const _avail = (currentProduct.status || '').toLowerCase() === 'live'
    ? 'https://schema.org/PreOrder'
    : (currentProduct.status || '').toLowerCase() === 'sold out'
      ? 'https://schema.org/SoldOut'
      : 'https://schema.org/PreOrder';
  /* ── MERGED ONTO THE SERVER'S COPY, NOT WRITTEN OVER IT ────────────────────
     functions/product/[slug].js already put a Product block in the head before
     the browser saw the page — that is what social crawlers read, since they do
     not run JavaScript. This used to REPLACE that element wholesale, which
     silently dropped every field the server knew and this file does not:
     `sku` was being deleted from the markup on every page load, and
     `aggregateRating` — the stars in a search result — would have been deleted
     the moment it was added.

     So: start from what the server wrote and update only the fields that depend
     on the selected colourway. The server is the source for anything it can
     resolve on its own; the browser is the source for what changes as somebody
     clicks around. Neither has to know the other's whole list. */
  const _ldEl = document.getElementById('product-ld-json') || document.createElement('script');
  let _ld = {};
  try { _ld = JSON.parse(_ldEl.textContent || '{}') || {}; } catch (_) { _ld = {}; }
  _ldEl.id = 'product-ld-json';
  _ldEl.type = 'application/ld+json';
  _ldEl.textContent = JSON.stringify({
    '@context': 'https://schema.org',
    '@type': 'Product',
    ..._ld,
    name: currentProduct.title || _ld.name || '',
    description: currentProduct.description || _ld.description || '',
    image: _pImg,
    url: _pUrl,
    brand: { '@type': 'Brand', name: 'ZUWERA' },
    offers: {
      ...(_ld.offers && typeof _ld.offers === 'object' ? _ld.offers : {}),
      '@type': 'Offer',
      priceCurrency: 'USD',
      price: _price,
      availability: _avail,
      url: _pUrl,
      seller: { '@type': 'Organization', name: 'ZUWERA' }
    }
  });
  if (!_ldEl.parentNode) document.head.appendChild(_ldEl);

  // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Price ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
  renderPrice();

  /* Ask the server what this actually costs — the only thing that knows about
     price lists, effective dates and customer groups (migration 0022). Without
     it this page showed $35 while the card was charged the approved list price
     of $30.

     Usually a no-op by now: variant-price.js fires the same request from the
     URL's product id on DOMContentLoaded, in parallel with the fetch that
     loaded this product, and ask() will not repeat one it has already sent.
     Kept because it is what covers a URL carrying a slug and no id. */
  if (window.ZWVariantPrice && currentProduct && currentProduct.id) {
    window.ZWVariantPrice.ask(currentProduct.id);
  }

  // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Gallery ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
  renderGallery();

  // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Colors ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
  renderColors();

  // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Inventory & Sizes ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
  renderSizes();

  // Related products
  void loadRelatedProducts();

  // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Accordions ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
  renderAccordions();

  // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Check low stock ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
  checkLowStock();

  // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Update Size Guide Link ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
  updateSizeGuideLink();
}

function normalizeGuideText(value) {
  return typeof value === 'string' ? value.trim() : '';
}

function resolveGuideGender(product) {
  const fields = [
    product?.gender,
    product?.audience,
    product?.gender_tag,
    product?.title,
    product?.subtitle,
  ];

  for (const field of fields) {
    const lower = normalizeGuideText(field).toLowerCase();
    if (!lower) continue;
    if (/(^|[^a-z])(women|woman|female|ladies)([^a-z]|$)/.test(lower)) return 'women';
    if (/(^|[^a-z])(men|man|male)([^a-z]|$)/.test(lower)) return 'men';
    if (/(kid|kids|youth|boys|girls|children)/.test(lower)) return 'kids';
  }

  return '';
}

function classifyGuideCategory(product) {
  const rawLabel = normalizeGuideText(product?.subtitle)
    || normalizeGuideText(product?.title)
    || 'Apparel';
  const lower = rawLabel.toLowerCase();

  if (/(sports?\s*bra|bra\b)/.test(lower)) {
    return { categoryLabel: rawLabel, calcCategory: 'sports_bras', tabId: 'sports_bras' };
  }
  if (/(hat|cap|beanie|visor)/.test(lower)) {
    return { categoryLabel: rawLabel, calcCategory: 'hats', tabId: 'hats' };
  }
  if (/sock/.test(lower)) {
    return { categoryLabel: rawLabel, calcCategory: 'socks', tabId: 'socks' };
  }
  if (/(short|jogger|legging|tight|pant|bottom|skirt)/.test(lower)) {
    return { categoryLabel: rawLabel, calcCategory: 'bottoms', tabId: '' };
  }
  if (/(tee|t-shirt|shirt|polo|hoodie|sweater|crew|jacket|puffer|zip|top|tank)/.test(lower)) {
    return { categoryLabel: rawLabel, calcCategory: 'tops', tabId: '' };
  }

  return { categoryLabel: rawLabel, calcCategory: 'tops', tabId: '' };
}

function getSizeGuideContext(product = currentProduct) {
  if (!product) return null;

  const gender = resolveGuideGender(product);
  const category = classifyGuideCategory(product);

  let tabId = category.tabId;
  if (!tabId) {
    if (gender === 'women') tabId = 'womens';
    else if (gender === 'kids') tabId = 'kids';
    else tabId = 'mens';
  }

  return {
    gender,
    tabId,
    calcCategory: category.calcCategory,
    categoryLabel: category.categoryLabel,
    focused: true
  };
}

function getSizeGuideModalMeta(context) {
  let label = singularizeGuideLabel(context?.categoryLabel);
  // Tops/bottoms use the broad category name so the title matches the size chart
  // (a jacket reads "Tops Size Guide", not "Jacket Size Guide"). Others keep their
  // own name (Hat, Sports Bra, Socks).
  if (context?.calcCategory === 'tops') label = 'Tops';
  else if (context?.calcCategory === 'bottoms') label = 'Bottoms';
  if (!label || label.toLowerCase() === 'apparel') {
    return {
      kicker: 'Fit Reference',
      title: 'Size Guide',
      copy: 'Compare measurements, find your starting size, and cross-check the exact category for this piece.'
    };
  }

  return {
    kicker: 'Fit Reference',
    title: `${label} Size Guide`,
    copy: `Compare measurements, find your starting size, and check the fit guidance for ${label.toLowerCase()}.`
  };
}

function syncSizeGuideModalMeta(context) {
  const meta = getSizeGuideModalMeta(context || getSizeGuideContext());
  const mKicker = document.getElementById('size-guide-modal-kicker');
  const mTitle  = document.getElementById('size-guide-modal-title');
  const mCopy   = document.getElementById('size-guide-modal-copy');
  if (mKicker) mKicker.textContent = meta.kicker;
  if (mTitle)  mTitle.textContent  = meta.title;
  if (mCopy)   mCopy.textContent   = meta.copy;
}

function updateSizeGuideLink() {
  const sizeGuideLink = document.getElementById('sizeGuideLink');
  const context = getSizeGuideContext();
  const sizeLabels = getAvailableProductSizes();
  const hideGuide = syncSizeGuideVisibility(sizeLabels);
  syncSizeGuideModalMeta(context);

  if (hideGuide) return;

  if (sizeGuideLink && context) {
    const params = new URLSearchParams();
    if (context.gender) params.set('gender', context.gender);
    if (context.categoryLabel) params.set('category', context.categoryLabel);
    if (context.calcCategory) params.set('guide', context.calcCategory);
    if (context.tabId) params.set('tab', context.tabId);
    if (context.focused) params.set('focused', 'true');
    if (selectedSize) params.set('size', selectedSize);
    sizeGuideLink.href = `/sizeguide.html?${params.toString()}`;
  }
}

async function ensureHatSizeGuideRows() {
  if (hatSizeGuideRowsCache) return hatSizeGuideRowsCache;
  if (hatSizeGuideRowsPromise) return hatSizeGuideRowsPromise;

  hatSizeGuideRowsPromise = (async () => {
    try {
      const { data, error } = await sb
        .from('size_charts')
        .select('size_label, head_circ_in, head_circ_cm')
        .eq('category', 'hats');

      if (error) throw error;

      const rows = Array.isArray(data) ? data.filter(row => row?.size_label) : [];
      hatSizeGuideRowsCache = rows.length
        ? rows.sort((left, right) => compareProductSizeLabels(left?.size_label || '', right?.size_label || ''))
        : [...fallbackHatSizeGuideRows];
    } catch (error) {
      console.log('Using fallback hat size guide rows:', error);
      hatSizeGuideRowsCache = [...fallbackHatSizeGuideRows];
    } finally {
      hatSizeGuideRowsPromise = null;
    }

    return hatSizeGuideRowsCache;
  })();

  return hatSizeGuideRowsPromise;
}

function findHatGuideRow(rows, sizeLabel) {
  const wanted = normalizeSizeLabel(sizeLabel);
  return rows.find(row => normalizeSizeLabel(row?.size_label) === wanted)
    || (isOneSizeLabel(sizeLabel) ? rows.find(row => isOneSizeLabel(row?.size_label)) : null)
    || rows[0]
    || null;
}

function isRenderableCssColor(value) {
  const candidate = String(value || '').trim();
  if (!candidate) return false;
  if (typeof CSS !== 'undefined' && typeof CSS.supports === 'function') {
    return CSS.supports('color', candidate);
  }
  return /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(candidate) || /^[a-z]+$/i.test(candidate);
}

function getColorwayFallbackStyle(colorwayLabel) {
  const rawLabel = String(colorwayLabel || '').trim();
  const parts = rawLabel
    .split(/[\/,|]+/)
    .map((part) => part.trim())
    .filter(Boolean);

  const renderableParts = parts.filter(isRenderableCssColor);
  if (renderableParts.length >= 2) {
    const stops = renderableParts
      .slice(0, 3)
      .map((color, index, array) => `${color} ${Math.round((index / array.length) * 100)}%, ${color} ${Math.round(((index + 1) / array.length) * 100)}%`)
      .join(', ');
    return {
      background: `linear-gradient(135deg, ${stops})`,
      border: '1px solid rgba(255,255,255,0.18)'
    };
  }

  if (renderableParts.length === 1) {
    return {
      backgroundColor: renderableParts[0],
      border: '1px solid rgba(255,255,255,0.18)'
    };
  }

  return {
    background: 'linear-gradient(135deg, rgba(255,255,255,0.14), rgba(255,255,255,0.04))',
    border: '1px solid rgba(255,255,255,0.18)'
  };
}

async function updateHatFitMeasurementInfo() {
  const fitMeasurementInfo = document.getElementById('fitMeasurementInfo');
  if (!fitMeasurementInfo) return;

  const context = getSizeGuideContext();
  if (!context || context.calcCategory !== 'hats') {
    fitMeasurementInfo.textContent = '';
    fitMeasurementInfo.style.display = 'none';
    return;
  }

  const guideRows = await ensureHatSizeGuideRows();
  const sizeLabels = getAvailableProductSizes();
  const oneSizeOnly = isSingleOneSizeProduct(sizeLabels);
  const activeSize = selectedSize || (oneSizeOnly ? (sizeLabels[0] || 'One Size') : null);

  if (!activeSize) {
    fitMeasurementInfo.textContent = 'Head Circumference: varies by size. Select a size or view the size guide.';
    fitMeasurementInfo.style.display = '';
    return;
  }

  const row = findHatGuideRow(guideRows, activeSize);

  if (!row) {
    fitMeasurementInfo.textContent = '';
    fitMeasurementInfo.style.display = 'none';
    return;
  }

  const measurementParts = [
    row.head_circ_in ? `${row.head_circ_in} in` : '',
    row.head_circ_cm ? `${row.head_circ_cm} cm` : ''
  ].filter(Boolean);

  if (!measurementParts.length) {
    fitMeasurementInfo.textContent = '';
    fitMeasurementInfo.style.display = 'none';
    return;
  }

  fitMeasurementInfo.textContent = `Head Circumference (${formatProductSizeLabel(row.size_label || activeSize)}): ${measurementParts.join(' / ')}`;
  fitMeasurementInfo.style.display = '';
}

// ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â
// RENDER PRICE
// ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â
/* ── Prices follow the SELECTED COLOUR ──────────────────────────────────────
   A colourway may carry its own price (migration 0021), so "what does this
   product cost" is not answerable until a colour is chosen. All three getters
   below take the product for their signature's sake and read the selected
   colour from module state, because every call site passes currentProduct — and
   a getter that silently ignored the colour would put the product price in the
   bag while the server charged the colour's, which is the never-bill-above-the
   -quote refusal landing on a shopper who did nothing wrong.

   The rule itself lives in variant-price.js, shared with the Worker that
   decides the charge and held to it by tests/variant-pricing.test.js. Nothing
   here re-derives it; when that file is missing these fall back to the product,
   which is what the page did before colours could be priced. */
function priceVariant() {
  return (typeof selectedColor !== 'undefined' && selectedColor) ? selectedColor : null;
}

function resolvedPrices(product) {
  if (window.ZWVariantPrice) {
    /* The SERVER's answer first, when it has arrived. The catalogue rule below
       knows nothing about price lists, effective dates or customer groups
       (migration 0022), so on its own it showed $35 for a product whose
       approved list price was $30 — and the card was charged $30. In the other
       direction, a list price above the catalogue one means checkout refuses
       the sale for exceeding the figure this page just displayed.

       Null until the ask returns, and then the catalogue answer stands — which
       is what this page showed before price lists existed. The zw:prices
       listener redraws when it lands. */
    const server = window.ZWVariantPrice.resolvedFor(
      product && product.id, (priceVariant() || {}).id
    );
    if (server && server.priceCents > 0) {
      /* EVERY figure from the server, including the member ones.
         This used to take priceCents from the server and then patch the member
         price in from the CATALOGUE, because /api/prices did not send one. Two
         consequences, both live on the site: a member already being charged $30
         by a price list was told "Members pay $35.00" beside it — the page
         advertising a worse price than the one it was about to charge — and a
         member price set on a price list could never appear at all.

         usingMember is likewise the server's answer rather than an equality
         test between two numbers that happened to match; the older
         `memberCents === priceCents` guess labelled an ordinary list price
         "Member price" whenever the two coincided. */
      const memberCents = Number(server.memberPriceCents) || 0;
      return {
        regularCents: Number(server.regularCents) || server.priceCents,
        memberCents,
        msrpCents: server.compareAtCents || 0,
        priceCents: server.priceCents,
        usingMember: Boolean(server.usingMember),
        source: server.source,
      };
    }
    /* THE FALLBACK, used when /api/prices could not be reached. It applies the
       catalogue rule here in the browser, so the store's member-pricing switch
       has to reach it too — otherwise a failed request is all it takes for a
       switched-off member price to reappear on the page. memberCents is cleared
       as well as the flag, because that field is what draws "Members pay $X"
       for a shopper who is not signed in. */
    const on = typeof window.ZWVariantPrice.memberPricingOn !== 'function'
      || window.ZWVariantPrice.memberPricingOn();
    const cat = window.ZWVariantPrice.resolve(product, priceVariant(), isMemberSignedIn() && on);
    return on ? cat : Object.assign({}, cat, { memberCents: 0, usingMember: false });
  }
  const regularCents = Math.round((parseFloat(product?.current_price ?? product?.price ?? 0) || 0) * 100);
  const memberCents  = Math.round((parseFloat(product?.member_price ?? 0) || 0) * 100);
  const useMember = isMemberSignedIn() && memberCents > 0 && (!regularCents || memberCents < regularCents);
  return {
    regularCents, memberCents,
    msrpCents: Math.round((parseFloat(product?.msrp ?? 0) || 0) * 100),
    priceCents: useMember ? memberCents : regularCents,
    usingMember: useMember, source: 'product',
  };
}

function getRegularProductPrice(product) {
  return resolvedPrices(product).regularCents / 100;
}

function getMemberProductPrice(product) {
  return resolvedPrices(product).memberCents / 100;
}

function getMsrpProductPrice(product) {
  return resolvedPrices(product).msrpCents / 100;
}

function isMemberSignedIn() {
  // __zwSessionUser is set synchronously pre-paint from the cached session (nav
  // auth script), whereas currentUser is only set ~0.5s later by auth.js's async
  // getSession. Consulting both means the FIRST renderPrice() already knows the
  // member is signed in, so the price shows member pricing immediately instead of
  // flashing regular → member once the session resolves.
  /* The server-verified answer wins once it exists. The two locals below are a
     PRESENCE check — they are true for a session object that expired an hour
     ago — and this decides which price the page advertises, so a stale one
     promises a discount checkout will not honour. They remain as the pre-paint
     guess, which is what they were good for. */
  if (typeof window.zwHasValidSession === 'function') return window.zwHasValidSession();
  return !!currentUser || !!window.__zwSessionUser;
}

function getEffectiveProductPrice(product) {
  return resolvedPrices(product).priceCents / 100;
}

/* The server's price landed. Redraw whatever showed the catalogue one.
   Same shape as the zw:tax listener in checkout: a figure drawn from cache,
   corrected in place the moment the real answer arrives. */
window.addEventListener('zw:prices', function () {
  try { if (currentProduct) { renderPrice(); syncProductSaveButton(); } } catch (_) {}
});

function syncProductSaveButton() {
  const btn = document.getElementById('saveProductBtn');
  if (!btn || !currentProduct?.id) return;
  btn.dataset.productId = currentProduct.id;
  btn.dataset.productName = currentProduct.title || currentProduct.name || 'Product';
  btn.dataset.price = String(getEffectiveProductPrice(currentProduct) || getRegularProductPrice(currentProduct) || 0);
  const firstImg = (currentProduct.images?.[0]?.image_url) || currentProduct.image_url || '';
  btn.dataset.productImage = firstImg;
  if (typeof refreshHeartButtons === 'function') refreshHeartButtons();
}

/* ── How the member badge reads (Builder → Product → Price) ────────────────
   Position, shape and wording. The three figures either side of it — what you
   pay, what it was, how much less — are not arranged here, because their right
   answer does not vary by store; a badge saying "member price" does.

   Read the same way the price itself is: from cache immediately, corrected by
   the server, and the price waits for BOTH before it prints. A badge that
   arrives a moment after the number and changes shape is the same flash in
   miniature, and this page has had enough of those. */
const PRICE_LOOK_DEFAULT = { member_position: 'inline', member_style: 'pill', member_label: '' };
const PRICE_LOOK_ALLOWED = {
  member_position: ['inline', 'below', 'hidden'],
  member_style: ['pill', 'plain', 'solid'],
};
let PRICE_LOOK = { ...PRICE_LOOK_DEFAULT };
let PRICE_LOOK_READY = false;

/* Clamped against the same lists the server enforces. The server already
   validates, so this is for the CACHE — a value stored before an option was
   renamed must not reach a class name that no stylesheet answers to. */
function normalisePriceLook(raw) {
  const out = { ...PRICE_LOOK_DEFAULT };
  if (raw && typeof raw === 'object') {
    for (const key of Object.keys(PRICE_LOOK_ALLOWED)) {
      if (PRICE_LOOK_ALLOWED[key].includes(raw[key])) out[key] = raw[key];
    }
    if (typeof raw.member_label === 'string') {
      /* Built rather than written as a literal. Typing this class by hand put
         RAW control bytes into the page — the Edit tool wrote the characters,
         not the escapes — which turns the file binary and is one keystroke
         from becoming a RANGE that strips every printable character. */
      out.member_label = raw.member_label
        .replace(new RegExp('[\\u0000-\\u001f\\u007f<>]', 'g'), '')
        .trim().slice(0, 24);
    }
  }
  return out;
}

(function loadPriceLook() {
  try {
    const cached = JSON.parse(localStorage.getItem('zw_pdp_price_v1') || 'null');
    if (cached) PRICE_LOOK = normalisePriceLook(cached);
  } catch (_) {}

  /* Settles once, however it goes. A layout read that fails must leave the
     shipped arrangement standing, not hold the price behind a placeholder. */
  let done = false;
  const settle = () => {
    if (done) return;
    done = true;
    PRICE_LOOK_READY = true;
    try { if (typeof currentProduct !== 'undefined' && currentProduct) renderPrice(); } catch (_) {}
  };
  setTimeout(settle, 4000);

  fetch('/api/product-page-config')
    .then((r) => (r.ok ? r.json() : null))
    .then((cfg) => {
      if (cfg && cfg.price) {
        PRICE_LOOK = normalisePriceLook(cfg.price);
        try { localStorage.setItem('zw_pdp_price_v1', JSON.stringify(PRICE_LOOK)); } catch (_) {}
      }
    })
    .catch(() => {})
    .then(settle);
})();

function renderPrice() {
  const p = resolvedPrices(currentProduct);

  /* --- A GIFT CARD IS WORTH WHAT THE BUYER CHOSE ---------------------------
     And nothing else on this line is true of one. Gift cards are excluded from
     promotions and member pricing at the till (see migration 0032: a 20% promo
     on a $100 card is the store paying the customer), so a struck-through
     figure or a "Member price" badge here advertises a discount checkout will
     refuse to give. Suppressed on the product BEING a gift card, not on an
     amount having been chosen -- the claim was wrong either way. */
  const isGC = isGiftCardProduct();
  /* The SELECTED COLOUR's compare-at, not the product's. A colourway with its
     own price inherits no compare-at, so reading currentProduct.msrp here would
     strike through a figure this colour never cost and advertise a saving
     nobody is offering. */
  const gcChosen = isGC ? gcChosenCents() : 0;
  const effective = gcChosen > 0 ? gcChosen / 100 : p.priceCents / 100;

  /* WHAT TO STRIKE THROUGH. One question, asked once.

     It used to be two labelled lines — "MSRP: $230" or "Regular: $40.00" —
     and neither word means anything to a shopper. MSRP is a trade term, and
     "Regular" invited the question "regular compared to what?". Every store
     that sells at a discount shows the same three things instead: what you
     pay, what it was, and how much less that is. The number carries the
     meaning, so the label can go.

     The compare-at is whichever is HIGHER of the colourway's compare-at and
     the price this shopper would otherwise have paid. A member looking at a
     $35 member price on a $40 product should see $40 struck through; a guest
     looking at a $176.97 sale price on a $220 product should see $220. Taking
     the higher of the two means one rule covers both rather than a branch per
     case — and a branch per case is how the old version ended up able to show
     "Regular" beside a price that was not a member discount at all. */
  const wasCents = isGC ? 0 : Math.max(p.msrpCents || 0, p.usingMember ? (p.regularCents || 0) : 0);
  const was = wasCents / 100;
  const saving = was > effective && was > 0
    /* FLOOR, not round. 12.5% rounds up to 13, and a store that advertises a
       bigger saving than it is giving has made a claim it cannot back — the
       shopper can do the subtraction. Rounding down understates it by less
       than a percent and is always defensible. */
    ? Math.floor(((was - effective) / was) * 100)
    : 0;

  const el = (id) => document.getElementById(id);

  /* ── NOTHING IS PRINTED UNTIL THE SERVER HAS ANSWERED ────────────────────
     "It still loads the old price first when you reload."

     It did, and removing the cache would not have fixed it — without a cached
     figure this drew the CATALOGUE price instead, which on a discounted product
     is just as wrong. The mistake was never which fallback to draw. It was
     drawing a price at all before knowing one.

     So the price waits, the way the tax total in checkout waits on isKnown():
     a figure the browser has not been told is not rendered as though it had
     been. The wait is one round trip, fired in parallel with the product fetch,
     and it settles to the fallback if the network fails. */
  const VP = window.ZWVariantPrice;
  const pricesKnown = !VP || typeof VP.known !== 'function'
    || VP.known(currentProduct && currentProduct.id);
  /* BOTH, before anything is printed. The figure and the shape of the badge
     beside it arrive from two different requests, and painting on the first to
     land means the price appears and then the badge changes under it. */
  const settled = pricesKnown && PRICE_LOOK_READY;
  if (!settled) {
    /* Fire the request from here too. ask() ignores an id it has already sent,
       so this costs nothing on the normal path — and it means the placeholder
       can never be permanent. A price area waiting forever on a request nobody
       made would be a far worse bug than the flash this replaces, and it is the
       kind that only shows up on the one code path somebody forgot. */
    try { VP.ask(currentProduct.id); } catch (_) {}
    el('priceDisplay').innerHTML = '<span class="zw-price-pending" aria-label="Loading price"></span>';
    el('msrpDisplay').innerHTML = '';
    el('memberPrice').innerHTML = '';
    syncProductSaveButton();
    return;
  }

  /* THE MEMBER LABEL BELONGS ON THE PRICE, not under it. It used to sit on its
     own line below the struck figure, which read as a footnote arriving after
     the fact — and when the member price is the only price shown, a trailing
     "Member price" looks like it is describing something else. Beside the
     number it is what it actually is: the name of the figure above it. */
  /* The badge, arranged by Builder -> Product -> Price. Escaped on the way in:
     the wording is merchant-typed free text on a public page, and sanitising it
     where it is stored is the belt, not the braces. */
  const escLabel = (v) => String(v == null ? '' : v)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const look = PRICE_LOOK;
  const badge = !isGC && p.usingMember && look.member_position !== 'hidden'
    ? `<span class="zw-price-member-tag zw-mtag-${look.member_style}">`
      + escLabel(look.member_label || 'Member price') + '</span>'
    : '';

  el('priceDisplay').innerHTML = effective > 0
    ? `<span class="zw-price-now">$${effective.toFixed(2)}</span>`
      + (look.member_position === 'inline' ? badge : '')
    : 'Price TBA';

  /* Struck-through figure and the saving sit together on one line, because
     they are one statement. A percentage with nothing beside it is a claim
     with no evidence.

     Rounded, and only shown from 1% — a "0% off" badge on a five-cent
     difference is worse than no badge, and it is what an unrounded
     calculation produces on a rounding artefact. */
  el('msrpDisplay').innerHTML = saving >= 1
    ? `<span class="zw-price-was">$${was.toFixed(2)}</span>`
      + `<span class="zw-price-off">${saving}% off</span>`
    : '';

  /* The member line says only what is TRUE. It used to print "Member savings
     applied" whenever the catalogue rule picked a member price, so it appeared
     beside a price-list figure that had discounted nothing. */
  const member = (p.memberCents || 0) / 100;
  const regular = (p.regularCents || 0) / 100;
  if (!isGC && p.usingMember) {
    /* Only when the badge was asked to live on its own line. Beside the price
       it has already been printed above, and saying it twice is the trailing
       line that made the member price look like an afterthought. */
    el('memberPrice').innerHTML = look.member_position === 'below' ? badge : '';
  } else if (member > 0 && member < regular) {
    el('memberPrice').innerHTML = `<span class="zw-price-member">Members pay $${member.toFixed(2)}</span>`;
  } else {
    el('memberPrice').innerHTML = '';
  }

  syncProductSaveButton();
}


