// RENDER GALLERY
// ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â
// ── Media helpers ──────────────────────────────────────────────────────────────
function isVideoMedia(item) {
  return item?.media_type === 'video' ||
    /\.(mp4|webm|mov|m4v|ogv)(\?.*)?$/i.test(item?.image_url || '');
}

function getImagesForColor(colorVariantId) {
  const all = currentProduct.allImages || currentProduct.images || [];
  const shared = all.filter(m => !m.color_variant_id);

  if (colorVariantId) {
    const specific = all.filter(m => m.color_variant_id === colorVariantId);
    if (specific.length) return [...specific, ...shared];
  }
  if (shared.length) return shared;

  // Last resort: ONE colourway's set — never `all`. Both branches used to fall
  // back to `all`, so a colour with no photos of its own and no shared photos
  // rendered every colourway's media in one gallery: 47 items on a product with
  // six per colour, mixing in videos that belong to other colours. Falling back
  // to the first colourway keeps the gallery coherent instead.
  const firstId = all.find(m => m.color_variant_id)?.color_variant_id;
  return firstId ? all.filter(m => m.color_variant_id === firstId) : all;
}

// Touch listener guard — only attach once, not once per renderGallery() call
let _galleryTouchSetup = false;

/**
 * "Dual" gallery arrangement — a horizontal filmstrip with two photos in view,
 * paged sideways by the arrows, rather than one image you page through in place.
 *
 * The arrows are the entire control surface here, so they are NOT hidden the way
 * they are in the other arrangements: they move into a row under the strip with
 * a position counter beside them, and page it one photo at a time.
 *
 * Builds into a sibling of .gallery-main so the original single-image markup
 * stays intact — switching back needs no re-render. No-ops (and cleans up after
 * itself) in every other arrangement.
 */
function renderDualGallery() {
  const section = document.querySelector('.gallery-section');
  const main = document.getElementById('galleryMain');
  if (!section) return;
  const g = window.ZWPdpGallery ? window.ZWPdpGallery.get() : null;
  const on = g && g.layout === 'dual';
  let strip = section.querySelector('.gallery-dual');
  const prev = document.getElementById('prevImg');
  const next = document.getElementById('nextImg');

  if (!on) {
    if (strip) strip.remove();
    const stale = section.querySelector('.gallery-dual-count');
    if (stale) stale.remove();
    if (main) main.style.display = '';
    if (prev) prev.disabled = false;
    if (next) next.disabled = false;
    return;
  }

  if (!strip) {
    strip = document.createElement('div');
    strip.className = 'gallery-dual';
    section.insertBefore(strip, main ? main.nextSibling : null);
  }
  if (main) main.style.display = 'none';   // the single-image area is unused here
  // display:none does NOT stop playback — a <video> keeps running (and holding a
  // decoder) while hidden. The single-image view's video element is unused in
  // this arrangement, so stop it and release the source rather than leaving it
  // playing behind the strip.
  const hiddenVid = document.getElementById('mainVideo');
  if (hiddenVid) {
    try { hiddenVid.pause(); } catch (_) {}
    hiddenVid.removeAttribute('src');
    try { hiddenVid.load(); } catch (_) {}
  }

  // Re-derive from the selected colourway rather than trusting whatever
  // currentProduct.images holds right now. It is assigned twice during load —
  // an unfiltered fallback at fetch time, then the colour-filtered set once the
  // images resolve — so a strip built in that window showed every image on the
  // product (both colourways) instead of the ones for the colour on screen.
  // Calling getImagesForColor is exactly what the thumbnails and main image do,
  // so the strip can no longer disagree with them.
  const media = (typeof getImagesForColor === 'function')
    ? getImagesForColor((typeof selectedColor !== 'undefined' && selectedColor) ? selectedColor.id : null)
    : (currentProduct.images || []);
  strip.innerHTML = '';
  media.forEach((item, idx) => {
    const url = item.image_url || '';
    const isVideo = /\.(mp4|webm|mov)(\?|#|$)/i.test(url);
    let node;
    if (isVideo) {
      node = document.createElement('video');
      node.src = url; node.muted = true; node.loop = true;
      node.playsInline = true; node.preload = 'metadata';
      // Deliberately NOT autoplay. Every video in the strip used to start at
      // once — including ones scrolled off to the side — so a clip kept running
      // (and decoding) behind whatever you were actually looking at. The
      // observer below plays only what's in view.
      node.dataset.zwStripVideo = '1';
    } else {
      node = document.createElement('img');
      node.src = typeof optimizeImage === 'function' ? optimizeImage(url, 900) : url;
      node.onerror = function () { if (this.src !== url) this.src = url; };
      node.alt = item.alt_text || `${currentProduct.title || 'Product'} view ${idx + 1}`;
      // The first two are in view immediately; the rest load as you page across.
      node.loading = idx < 2 ? 'eager' : 'lazy';
      node.decoding = 'async';
    }
    // Same class the single-image gallery uses for its load animation, so the
    // admin's Gallery Animation setting (body[data-gal-load]) drives the strip
    // too. Without it the dual layout built its images with no animation at all.
    // Staggered slightly so the strip resolves left-to-right instead of every
    // photo popping at once.
    node.classList.add('zw-img-in');
    node.style.animationDelay = Math.min(idx, 5) * 45 + 'ms';
    strip.appendChild(node);
  });

  // Put the arrows (and a counter) in a row beneath the strip. ZWPdpGallery
  // MOVES the existing buttons, so their handlers survive — but those handlers
  // page the single-image view, so they get re-pointed at the strip below.
  if (window.ZWPdpGallery) {
    window.ZWPdpGallery.applyTo(section, g.thumbs, 'below', 'dual', '.gallery-arrow');
  }
  const row = section.querySelector('.gallery-nav-below');
  let count = section.querySelector('.gallery-dual-count');
  if (row && !count) {
    count = document.createElement('span');
    count.className = 'gallery-dual-count';
  }
  // Re-append AFTER applyTo, every time. applyTo moves the arrows to the end of
  // the row on each call, so a counter appended once ends up in front of them on
  // the second render (colourway switch, config settle, resize) — reading
  // "1/17 ‹ ›" instead of "‹ › 1/17". Pushing it last each time pins the order.
  if (row && count) row.appendChild(count);

  const step = () => {
    const first = strip.firstElementChild;
    if (!first) return strip.clientWidth / 2;
    // Measured, not assumed: the flex-basis differs between desktop (two in
    // view) and the ≤900px fallback (one), and the gap counts.
    return first.getBoundingClientRect().width + parseFloat(getComputedStyle(strip).gap || 0);
  };
  const sync = () => {
    const s = step();
    // maxScroll is the furthest the strip can go — 0 when everything already fits.
    const maxScroll = strip.scrollWidth - strip.clientWidth;
    const atEnd = strip.scrollLeft >= maxScroll - 1;
    const idx = s ? Math.round(strip.scrollLeft / s) : 0;
    // The counter names the LEFTMOST photo in view — except at the far end,
    // where the strip stops with the last two showing and the leftmost is N-1.
    // Reporting N-1 there reads as "there's more" when there isn't, so the last
    // position counts as the last photo.
    if (count) {
      // `maxScroll > 0` guard: with few enough photos to fit, atEnd is true from
      // the start, and without this a 2-image product would open reading "2/2".
      const shown = (atEnd && maxScroll > 0 && media.length)
        ? media.length
        : Math.min(idx + 1, media.length);
      count.textContent = `${shown}/${media.length}`;
    }
    if (prev) prev.disabled = strip.scrollLeft <= 1;
    if (next) next.disabled = atEnd;
  };

  if (prev) prev.onclick = () => { strip.scrollBy({ left: -step(), behavior: 'smooth' }); };
  if (next) next.onclick = () => { strip.scrollBy({ left:  step(), behavior: 'smooth' }); };
  if (!strip._zwSyncBound) {
    strip._zwSyncBound = true;
    strip.addEventListener('scroll', sync, { passive: true });
    window.addEventListener('resize', sync);
  }

  // Play a strip video only while it is actually in view, pause it the moment it
  // scrolls out. Same approach the collection grid uses for card videos, and the
  // reason none of them bleed through from off-screen any more. Rebuilt with the
  // strip, so the observer is recreated rather than accumulating targets.
  if (strip._zwVidObs) { try { strip._zwVidObs.disconnect(); } catch (_) {} }
  if ('IntersectionObserver' in window) {
    strip._zwVidObs = new IntersectionObserver((entries) => {
      entries.forEach((en) => {
        const v = en.target;
        if (en.isIntersecting) { const p = v.play(); if (p && p.catch) p.catch(() => {}); }
        else { try { v.pause(); } catch (_) {} }
      });
    }, { root: strip, threshold: 0.35 });
    strip.querySelectorAll('video[data-zw-strip-video]').forEach(v => strip._zwVidObs.observe(v));
  } else {
    // No observer support: play the first video only, rather than all of them.
    const first = strip.querySelector('video[data-zw-strip-video]');
    if (first) { const p = first.play(); if (p && p.catch) p.catch(() => {}); }
  }

  sync();
}

// The gallery usually renders before the config request resolves, so re-run once
// it lands. Cached config makes this a no-op on a repeat visit.
if (window.ZWPdpGallery) {
  window.ZWPdpGallery.ready(function () {
    // Wait for allImages — it is only set once the real image rows resolve.
    // Keying off currentProduct.images instead would fire against the fetch-time
    // fallback and build the strip from the wrong set. renderGallery calls this
    // again anyway once the images land, so skipping early costs nothing.
    if (window.currentProduct && currentProduct.allImages) {
      try { renderDualGallery(); } catch (_) {}
    }
  });
}

function renderGallery() {
  const mainImage = document.getElementById('mainImage');
  const mainVideo = document.getElementById('mainVideo');
  const thumbContainer = document.getElementById('galleryThumbnails');
  thumbContainer.innerHTML = '';

  if (!currentProduct.images || currentProduct.images.length === 0) {
    mainImage.style.display = '';
    if (mainVideo) { mainVideo.style.display = 'none'; mainVideo.src = ''; }
    mainImage.src = 'data:image/svg+xml,%3Csvg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 500"%3E%3Crect fill="transparent" width="400" height="500"/%3E%3C/svg%3E';
    mainImage.alt = 'No image available';
    return;
  }

  // Preserve index across color switches; clamp to new length. This path runs on
  // first paint and colorway switches → use the soft fade, not the slide.
  currentImageIndex = Math.max(0, Math.min(currentImageIndex, currentProduct.images.length - 1));
  updateMainImage(currentImageIndex, 'fade');

  document.getElementById('prevImg').onclick = () => updateMainImage(currentImageIndex - 1);
  document.getElementById('nextImg').onclick = () => updateMainImage(currentImageIndex + 1);

  // MUST come after the two lines above: in the dual arrangement the arrows page
  // the filmstrip instead of the single image, and renderDualGallery re-points
  // their onclick. Called earlier, these assignments would overwrite it and the
  // arrows would silently drive the hidden single-image view.
  // Rebuilt on every renderGallery so a colourway switch swaps the strip's set.
  renderDualGallery();

  // Mobile swipe — attach ONCE. Re-registering on every renderGallery() call
  // (e.g. every color switch) stacks listeners, causing one swipe to fire N times.
  if (!_galleryTouchSetup) {
    _galleryTouchSetup = true;
    let touchStartX = 0;
    const galleryMain = document.querySelector('.gallery-main');
    galleryMain.addEventListener('touchstart', e => { touchStartX = e.changedTouches[0].screenX; }, {passive: true});
    galleryMain.addEventListener('touchend', e => {
      const dx = e.changedTouches[0].screenX - touchStartX;
      if (dx < -40) updateMainImage(currentImageIndex + 1);
      if (dx > 40)  updateMainImage(currentImageIndex - 1);
    }, {passive: true});
  }

  currentProduct.images.forEach((item, idx) => {
    const thumb = document.createElement('div');
    thumb.className = 'thumbnail' + (idx === currentImageIndex ? ' active' : '');

    if (isVideoMedia(item)) {
      // Video thumbnail — play icon overlay
      const wrap = document.createElement('div');
      wrap.style.cssText = 'width:100%;height:100%;background:#09090b;display:flex;align-items:center;justify-content:center;';
      wrap.innerHTML = '<svg width="28" height="28" viewBox="0 0 28 28" aria-hidden="true"><circle cx="14" cy="14" r="14" fill="rgba(0,0,0,.55)"/><polygon points="11,9 21,14 11,19" fill="white"/></svg>';
      thumb.appendChild(wrap);
    } else {
      const thumbImg = document.createElement('img');
      thumbImg.src = optimizeImage(item.image_url, 200);
      thumbImg.onerror = function() { if (this.src !== item.image_url) this.src = item.image_url; };
      thumbImg.alt = item.alt_text || `${currentProduct.title} view ${idx + 1}`;
      thumbImg.loading = 'lazy';
      thumb.appendChild(thumbImg);
      // Preload into cache
      const p = new Image(); p.src = item.image_url;
    }

    // Hover any thumbnail (image OR video) to preview it in the main area; it
    // stays until another thumbnail is hovered/clicked or the gallery is advanced.
    // Video is muted+playsinline, so hovering its thumbnail autoplays it.
    thumb.addEventListener('mouseenter', () => { if (idx !== currentImageIndex) updateMainImage(idx); });
    thumb.addEventListener('click', () => updateMainImage(idx));
    thumbContainer.appendChild(thumb);
  });

  renderGalleryDots();
}

// Mobile carousel position indicator — one dot per media item, active one
// elongated (Nike-style pill). Hidden via CSS on desktop (the thumbnail strip
// shows position there) and when there's only a single image.
function renderGalleryDots() {
  const dotsEl = document.getElementById('galleryDots');
  if (!dotsEl) return;
  const n = (currentProduct.images || []).length;
  if (n <= 1) { dotsEl.innerHTML = ''; dotsEl.classList.remove('has-dots'); return; }
  dotsEl.classList.add('has-dots');
  let html = '';
  for (let i = 0; i < n; i++) html += `<span class="gallery-dot${i === currentImageIndex ? ' active' : ''}"></span>`;
  dotsEl.innerHTML = html;
}
function setActiveGalleryDot(index) {
  const dotsEl = document.getElementById('galleryDots');
  if (!dotsEl) return;
  dotsEl.querySelectorAll('.gallery-dot').forEach((d, i) => d.classList.toggle('active', i === index));
}

function updateMainImage(index, mode) {
  // mode: 'slide' = directional carousel (swipe / arrows / thumbnails),
  //       'fade'  = soft fade+settle (colorway switch / first paint).
  mode = mode || 'slide';
  const images = currentProduct.images;
  if (!images || !images.length) return;
  const _prevIndex = currentImageIndex;
  if (index < 0) index = images.length - 1;
  if (index >= images.length) index = 0;
  // Carousel direction: +1 forward (new photo enters from the right), -1 back
  // (enters from the left). Handles wrap-around at the ends.
  let _slideDir = 1;
  if (index !== _prevIndex) {
    _slideDir = index > _prevIndex ? 1 : -1;
    if (_prevIndex === images.length - 1 && index === 0) _slideDir = 1;
    else if (_prevIndex === 0 && index === images.length - 1) _slideDir = -1;
  }
  currentImageIndex = index;

  const item = images[index];
  const mainImgEl = document.getElementById('mainImage');
  const mainVidEl = document.getElementById('mainVideo');
  const galleryMain = document.getElementById('galleryMain');

  if (isVideoMedia(item)) {
    mainImgEl.style.display = 'none';
    if (mainVidEl) {
      mainVidEl.src = item.image_url;
      mainVidEl.style.display = '';
      mainVidEl.load();
      mainVidEl.play().catch(() => {});
    }
    galleryMain?.classList.remove('loading');
  } else {
    if (mainVidEl) { mainVidEl.style.display = 'none'; mainVidEl.pause(); mainVidEl.src = ''; }
    mainImgEl.style.display = '';
    // Animate the swap: a directional carousel slide for photo navigation, or a
    // soft fade+settle for colorway switches / first paint. Thumbnails are
    // preloaded, so the next image is usually cached and it plays at once.
    const _animMainImg = () => {
      galleryMain?.classList.remove('loading');
      mainImgEl.classList.remove('zw-img-in', 'zw-slide-next', 'zw-slide-prev');
      void mainImgEl.offsetWidth;          // restart the animation each time
      if (mode === 'fade') mainImgEl.classList.add('zw-img-in');
      else mainImgEl.classList.add(_slideDir < 0 ? 'zw-slide-prev' : 'zw-slide-next');
    };
    mainImgEl.src = optimizeImage(item.image_url, 1200);
    mainImgEl.onload  = _animMainImg;
    mainImgEl.onerror = function() {
      _animMainImg();
      if (this.src !== item.image_url) this.src = item.image_url;
    };
    mainImgEl.alt = item.alt_text || currentProduct.title;
  }

  document.querySelectorAll('.thumbnail').forEach((t, i) => t.classList.toggle('active', i === index));
  setActiveGalleryDot(index);
}

// ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â
// RENDER COLORS
// ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â
// Colorway swatches show a PRODUCT THUMBNAIL of each colour (Nike-style), not a
// flat colour chip. Falls back to the hex chip if that colour has no image yet
// (e.g. images still loading — updateColorwayThumbnails() upgrades them after).
function colorwayThumbSrc(color) {
  if (!color || !currentProduct || !currentProduct.allImages) return '';
  const cimgs = getImagesForColor(color.id);
  const firstImg = cimgs.find((m) => !isVideoMedia(m)) || cimgs[0];
  return (firstImg && firstImg.image_url) ? optimizeImage(firstImg.image_url, 240) : '';
}
/* WITHDRAWN: this drew a real <img class="zw-swatch-thumb"> so that a failing
   Cloudinary URL would reach the fallback chain in image-utils.js, which a CSS
   background cannot — a background that 404s fires no error event anywhere.

   On the deployed site the shared sizing rule did not reach the element. Every
   swatch in all five renderers drew at the <img>'s intrinsic size instead: the
   colourway picker at 240px inside a 68x54 tile, the card swatches at 600px
   inside 20px, spilling across the card and over the Add to Bag button. The
   rule is present, valid, top-level and in a stylesheet each page loads — I
   could not reproduce it without a browser, and this is live on the three
   busiest pages, so the background is back until it can be shown working.

   What that gives up is written down in [[storefront-features-module]]: if
   Cloudinary goes over quota the swatches go blank while the tiles keep their
   size, which is a failure that does not look like one.

   Called twice — once when the colours arrive and again from
   updateColorwayThumbnails() once the images resolve — so it stays idempotent,
   and it clears any <img> a previously cached script left behind. */
function applyColorwaySwatchVisual(swatch, color) {
  const src = colorwayThumbSrc(color);
  const stale = swatch.querySelector('img.zw-swatch-thumb');
  if (stale) stale.remove();
  if (src) {
    swatch.style.backgroundImage = `url('${src}')`;
    swatch.style.backgroundColor = '';
    swatch.classList.add('has-thumb');
  } else {
    swatch.style.backgroundImage = '';
    swatch.style.backgroundColor = color.hex_color || '#888';
    swatch.classList.remove('has-thumb');
  }
}
// After images resolve (they race the colour fetch), upgrade the chips to thumbs.
function updateColorwayThumbnails() {
  if (!currentProduct || !currentProduct.colors) return;
  const swatches = document.querySelectorAll('#colorSwatches .color-swatch');
  currentProduct.colors.forEach((color, idx) => {
    if (swatches[idx]) applyColorwaySwatchVisual(swatches[idx], color);
  });
}
// Mobile: move the colourway picker directly under the photo (replacing the
// angle-thumbnail strip, which is hidden on mobile). Desktop keeps it in the
// info column. Re-runs on resize across the breakpoint.
let _colorwayViewportSetup = false;
function placeColorwayForViewport() {
  const cw = document.querySelector('.colorway-section');
  const gallerySection = document.querySelector('.gallery-section');
  const infoSection = document.querySelector('.info-section');
  if (!cw || !gallerySection || !infoSection) return;
  if (window.matchMedia('(max-width: 768px)').matches) {
    if (cw.parentNode !== gallerySection) gallerySection.appendChild(cw);
  } else if (cw.parentNode !== infoSection) {
    const sizeSection = infoSection.querySelector('.size-section');
    if (sizeSection) infoSection.insertBefore(cw, sizeSection); else infoSection.appendChild(cw);
  }
}

// Selected-colour label = a mini colour box (the colour's hex) + the name.
function setSelectedColorLabel(color) {
  const el = document.getElementById('selectedColor');
  if (!el) return;
  el.innerHTML = '';
  const hex = color && color.hex_color;
  if (hex) {
    const box = document.createElement('span');
    box.className = 'selected-color-box';
    box.style.background = hex;
    el.appendChild(box);
  }
  const name = document.createElement('span');
  name.textContent = (color && color.color_name) || '';
  el.appendChild(name);
}

function renderColors() {
  const container = document.getElementById('colorSwatches');
  const colorwaySection = document.querySelector('.colorway-section');
  container.innerHTML = '';
  if (colorwaySection) colorwaySection.style.display = '';

  if (currentProduct.colors.length === 0) {
    // Fall back to colorway field from main product data
    if (currentProduct.colorway && currentProduct.colorway.trim()) {
      container.innerHTML = '';
      const colorwayLabel = currentProduct.colorway.trim();
      setSelectedColorLabel({ color_name: colorwayLabel });
      const swatch = document.createElement('button');
      swatch.className = 'color-swatch active';
      swatch.type = 'button';
      swatch.title = colorwayLabel;
      swatch.setAttribute('aria-label', colorwayLabel);
      swatch.setAttribute('data-color-name', colorwayLabel);
      Object.assign(swatch.style, getColorwayFallbackStyle(colorwayLabel));
      container.appendChild(swatch);
      selectedColor = null;
      selectedColorSku = null;
      return;
    }
    if (colorwaySection) colorwaySection.style.display = 'none';
    return;
  }

  // Prefer a deep-linked colour (?color= from an email/share) over the first swatch.
  let _initColorIdx = 0;
  if (_pendingColor) {
    const _nc = String(_pendingColor).trim().toLowerCase();
    const _fi = currentProduct.colors.findIndex(c => String(c.color_name || '').trim().toLowerCase() === _nc);
    if (_fi >= 0) _initColorIdx = _fi;
  }

  currentProduct.colors.forEach((color, idx) => {
    const swatch = document.createElement('button');
    swatch.className = 'color-swatch';
    if (idx === _initColorIdx) {
      swatch.classList.add('active');
      selectedColor = color;
      selectedColorSku = color.variant_sku;
      setSelectedColorLabel(color);
      // If images already loaded (colors resolved after images in the parallel fetch race),
      // re-filter now so the selected color's gallery shows immediately without needing a click.
      if (currentProduct.allImages) {
        currentProduct.images = getImagesForColor(color.id);
        currentImageIndex = 0;
        renderGallery();
      }
    }

    applyColorwaySwatchVisual(swatch, color);
    swatch.title = color.color_name;
    swatch.setAttribute('data-color-name', color.color_name);

    swatch.addEventListener('click', (e) => {
      e.preventDefault();
      document.querySelectorAll('.color-swatch').forEach(s => s.classList.remove('active'));
      swatch.classList.add('active');
      selectedColor = color;
      selectedColorSku = color.variant_sku;
      setSelectedColorLabel(color);
      selectedSize = null;
      renderSizes();
      // Switch gallery to this color's media, preserving position
      if (currentProduct.allImages) {
        currentProduct.images = getImagesForColor(color.id);
        renderGallery();
      }
      /* A colourway may cost something different (migration 0021), so the price
         is part of what a swatch changes — not only the pictures. Without this
         the page would keep showing the previous colour's price while the
         server charges this one's, and the never-bill-above-the-quote guard
         would refuse the sale at the till. */
      renderPrice();
      syncProductSaveButton();
    });

    container.appendChild(swatch);
  });

  setSelectedColorLabel(currentProduct.colors[0]);

  placeColorwayForViewport();
  if (!_colorwayViewportSetup) {
    _colorwayViewportSetup = true;
    window.addEventListener('resize', placeColorwayForViewport, { passive: true });
  }
}

// ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â
// RENDER SIZES
// ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â
// Stock is tracked PER COLOUR. Return the stock for a size in the given colour,
// preferring exact-colour rows, then falling back to colour-agnostic rows
// (color_name NULL) for products saved before per-colour stock existed. With no
// colour, use the NULL rows if present, else sum across colours.
function sizeStockForColor(sizeLabel, colorName) {
  const inv = Array.isArray(currentProduct?.inventory) ? currentProduct.inventory : [];
  // Canonicalize the size so equivalent labels match: the size button is built
  // with formatProductSizeLabel ("2XL" → "XXL") but inventory may store "2XL".
  // canonicalizeProductSizeToken folds xxl↔2xl, xxxl↔3xl, xxs↔2xs, etc.
  const norm = canonicalizeProductSizeToken(sizeLabel);
  const rows = inv.filter(r => canonicalizeProductSizeToken(r?.size) === norm);
  if (!rows.length) return 0;
  const sum = list => list.reduce((s, r) => s + (r?.stock_quantity || 0), 0);
  if (colorName) {
    // Normalize colour (trim + lowercase) so a case/whitespace difference between
    // the product_sizes row and the colour swatch doesn't read as "sold out".
    const nc = String(colorName).trim().toLowerCase();
    const colorRows = rows.filter(r => String(r.color_name || '').trim().toLowerCase() === nc);
    if (colorRows.length) return sum(colorRows);
    const nullRows = rows.filter(r => !r.color_name);
    return nullRows.length ? sum(nullRows) : 0;
  }
  const nullRows = rows.filter(r => !r.color_name);
  return nullRows.length ? sum(nullRows) : sum(rows);
}

function renderSizes() {
  const sizeGrid = document.getElementById('sizeGrid');
  sizeGrid.innerHTML = '';

  /* Close any open back-in-stock panel first. This re-runs when the COLOUR
     changes, and the panel was left standing — so opening it for a sold-out M
     in one colourway and then switching to a colour where M is in stock left
     "Size M is sold out" sitting under a size that was available, saying it
     regardless of what the page above had just worked out.
     quick-add-modal.js has always reset its own panel on every render; this is
     the same rule, arriving late. */
  hideRestockPanel();

  // Per-colour stock for the SELECTED colour (falls back to colour-agnostic rows for
  // legacy products — see sizeStockForColor). renderSizes re-runs when the colour
  // changes, so availability reflects the chosen colourway.
  const _selColorName = (selectedColor && selectedColor.color_name) || null;
  const sizeMap = new Map();
  currentProduct.inventory.forEach(inv => {
    const sizeLabel = formatProductSizeLabel(inv?.size);
    if (!sizeLabel || sizeMap.has(sizeLabel)) return;
    sizeMap.set(sizeLabel, sizeStockForColor(sizeLabel, _selColorName));
  });

  // Standard size order ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â always show these
  const hasInventory = sizeMap.size > 0;
  const sizes = getAvailableProductSizes();
  const previousSelectedSize = selectedSize;
  const oneSizeOnly = isSingleOneSizeProduct(sizes);
  syncSizeGuideVisibility(sizes);

  sizes.forEach(size => {
    const stock = hasInventory ? (sizeMap.get(size) || 0) : -1;
    const btn = document.createElement('button');
    btn.className = 'size-btn';
    btn.textContent = size;
    btn.dataset.size = size;

    if (hasInventory && stock === 0) {
      // Sold out: stays clickable so it can open the back-in-stock capture
      // instead of being a dead end. .disabled keeps the struck-through look;
      // aria reflects the real affordance.
      btn.classList.add('disabled');
      // Same sentence a sighted shopper gets, from the same editable message.
      btn.setAttribute('aria-label', ZWStock.msg('restockPrompt', { size }));
    }

    btn.addEventListener('click', () => {
      if (hasInventory && stock === 0) {
        /* SELECT it as well as offering the waitlist. This used to return here,
           so a sold-out size could never become the selected one — which meant
           updateStockInfo() never ran for it and the line under the sizes never
           said "Out of stock". Clicking a sold-out size, the obvious way anyone
           would try to find that message, was the one way that could not.

           The strikethrough was doing all the work alone. Now the line
           underneath says what is wrong and the panel offers the fix. */
        document.querySelectorAll('.size-btn').forEach(b => b.classList.remove('selected'));
        btn.classList.add('selected');
        selectedSize = size;
        // Panel first: updateStockInfo defers to it rather than repeating it.
        openRestockPanel(size);
        updateStockInfo();
        updateSizeGuideLink();
        return;
      }
      hideRestockPanel();
      document.querySelectorAll('.size-btn').forEach(b => b.classList.remove('selected'));
      btn.classList.add('selected');
      selectedSize = size;
      updateStockInfo();
      updateSizeGuideLink();
    });

    sizeGrid.appendChild(btn);
  });

  // A deep-linked size (?size=) wins on first render — consumed once so switching
  // colour afterwards doesn't keep forcing it. Canonicalized so 2XL/XXL match.
  let _pendingSizeMatch = null;
  if (_pendingSize) {
    const _ps = canonicalizeProductSizeToken(_pendingSize);
    _pendingSizeMatch = sizes.find((s) => canonicalizeProductSizeToken(s) === _ps) || null;
    _pendingSize = null;
  }
  const preferredSize = _pendingSizeMatch
    || (oneSizeOnly
      ? sizes[0]
      : (previousSelectedSize && sizes.includes(previousSelectedSize) ? previousSelectedSize : null));

  if (preferredSize) {
    const preferredButton = Array.from(sizeGrid.querySelectorAll('.size-btn'))
      .find((button) => button.dataset.size === preferredSize && !button.disabled);
    if (preferredButton) {
      preferredButton.classList.add('selected');
      selectedSize = preferredSize;
    } else if (oneSizeOnly) {
      selectedSize = preferredSize;
    }
  } else if (!sizes.includes(selectedSize)) {
    selectedSize = null;
  }

  updateStockInfo();
  updateSizeGuideLink();
  void updateHatFitMeasurementInfo();
}

// ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â
// UPDATE STOCK INFO
// ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â
/* The admin's wording arrives over the network, after this page has already
   drawn its stock line. Repaint when it lands, or an edit only shows up for
   whoever happens to reload at the right moment.

   Subscribed on DOMContentLoaded rather than here: customer-messages.js is a
   DEFERRED script on this page, so it has not run yet while this block is being
   parsed and window.ZWMessages does not exist. Deferred scripts do run before
   DOMContentLoaded, so by then it is there. */
(function subscribeToMessageChanges() {
  function attach() {
    if (!window.ZWMessages || !ZWMessages.subscribe) return;
    ZWMessages.subscribe(function () {
      try { if (typeof selectedSize !== 'undefined' && selectedSize) updateStockInfo(); } catch (_) {}
      /* Unconditional: the delivery copy is drawn before an admin's edits land
         and there is no size to have selected on a gift card page. */
      try { paintGiftCardDelivery(); } catch (_) {}
    });
  }
  if (window.ZWMessages) attach();
  else document.addEventListener('DOMContentLoaded', attach, { once: true });
})();

function updateStockInfo() {
  if (!selectedSize) {
    document.getElementById('stockInfo').textContent = '';
    return;
  }

  // If no inventory data exists at all, allow adding to cart
  if (currentProduct.inventory.length === 0) {
    document.getElementById('stockInfo').textContent = '';
    document.getElementById('addToCartBtn').disabled = false;
    document.getElementById('addToCartBtn').classList.remove('disabled');
    return;
  }

  const onShelf = sizeStockForColor(selectedSize, (selectedColor && selectedColor.color_name) || null);

  /* Counts describe what the shopper can still ADD; only the shelf decides
     whether something is sold out.

     Those used to be one number, and it was wrong in a way that cost sales:
     with one left and that one in the shopper's own bag, this said "Out of
     stock". Nothing had sold. Stock comes off the shelf when a payment
     succeeds and at no other moment, so a bag — which anyone can fill with no
     intention of buying — must never be able to print that sentence.

     ZWStock.availability keeps the two apart. Falls back to the raw shelf
     figure if the shared rules have not loaded, which only over-offers by
     whatever is in the bag and never invents a sell-out. */
  let avail = null;
  try {
    if (window.ZWStock && ZWStock.availability) {
      const cart = JSON.parse(localStorage.getItem('cart') || '[]');
      avail = ZWStock.availability(onShelf, {
        productId: currentProduct.id,
        size: selectedSize,
        colorName: (selectedColor && selectedColor.color_name) || '',
      }, cart);
    }
  } catch (_) {}
  if (!avail) {
    avail = { onShelf, inBag: 0, left: onShelf, soldOut: onShelf === 0, heldByYou: false, canAdd: onShelf !== 0 };
  }

  const threshold = currentProduct.low_stock_threshold || 10;
  const info = document.getElementById('stockInfo');
  const btn = document.getElementById('addToCartBtn');
  const setBtn = (enabled) => {
    btn.disabled = !enabled;
    btn.classList.toggle('disabled', !enabled);
  };

  // Wording from ZWMessages so the admin can edit it; see customer-messages.js.
  if (avail.soldOut) {
    /* Genuinely gone: someone paid for the last one.

       Say it ONCE. When the back-in-stock panel is open it already opens with
       "Size M is sold out — get notified when it's back", so printing "Out of
       stock" underneath states the same fact a second time, and states it below
       the thing offering the remedy. The line speaks when the panel is not
       there — switching to a colourway where the selected size has gone, or a
       deep link straight to a sold-out size. */
    const panel = document.getElementById('restock-panel');
    const panelSpeaking = !!panel && panel.style.display === 'block';
    info.textContent = panelSpeaking ? '' : ZWStock.msg('soldOut');
    setBtn(false);
  } else if (avail.heldByYou) {
    /* Still in stock — they are holding it. Add to Bag is off because there is
       nothing left to add, but the wording says whose bag it is in, so it
       cannot be read as the store having sold out. Matches the toast the add
       handler shows for the same situation. */
    info.textContent = avail.inBag === 1
      ? ZWStock.msg('lastInBag')
      : ZWStock.msg('allInBag', { count: avail.inBag });
    setBtn(false);
  } else if (avail.left <= threshold) {
    info.textContent = ZWStock.msg('lowStock', { count: avail.left });
    setBtn(true);
  } else {
    info.textContent = '';
    setBtn(true);
  }
}

