// ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â
function renderReviews() {
  const content = document.getElementById('reviewsContent');
  // Pull the admin-configured "collapse reviews longer than" cutoff (defined in
  // reviews.js) once it's loaded, then re-render so existing long reviews collapse.
  if (!window._reviewLimitsSynced && typeof ensureReviewLimits === 'function') {
    window._reviewLimitsSynced = true;
    ensureReviewLimits().then(() => renderReviews());
  }
  const safeEsc = typeof escHtml === 'function'
    ? escHtml
    : (value) => String(value ?? '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  content.innerHTML = '';

  if (!currentProduct.reviews || currentProduct.reviews.length === 0) {
    content.innerHTML = '<p style="opacity: 0.6;">No reviews yet</p>';
    return;
  }

  // Calculate average rating
  const avgRating = (currentProduct.reviews.reduce((sum, r) => sum + r.rating, 0) / currentProduct.reviews.length).toFixed(1);

  /* Guarded, like the two other call sites already were. reviews.js is deferred
     now, and although renderReviews() runs off the async product fetch — long
     after any deferred script — an unguarded call is a dependency on that
     timing rather than on anything stated. When it is not there yet, the
     summary is skipped and the next render fills it in; the reviews themselves
     below are rendered by this page regardless. */
  content.innerHTML = typeof generateReviewSummaryHtml === 'function'
    ? generateReviewSummaryHtml(currentProduct.reviews)
    : '';

  // Update header
  document.getElementById('reviewsHeader').textContent =
    `Reviews (${avgRating} \u00b7 ${currentProduct.reviews.length})`;

  // Show up to the first 6 reviews inline in the column (Nike-style), so people
  // read reviews without opening anything. The modal stays for photos / the rest.
  const displayReviews = currentProduct.reviews.slice(0, 6);

  displayReviews.forEach(review => {
    const reviewEl = document.createElement('div');
    reviewEl.className = 'review-item';
    const productId = String(currentProduct?.id || '').replace(/'/g, "\\'");
    const adminResponseHtml = review.admin_response ? `
      <div class="admin-response" style="margin-top: 12px; padding: 12px; background: var(--admin-res-bg, rgba(248,145,165,0.08)); border-left: 2px solid var(--admin-res-text, #F891A5); border-radius: 4px;">
        <strong style="color: var(--admin-res-text, #F891A5); font-size: 0.85rem; letter-spacing: 0.05em; font-family:var(--font-head);">Zuwera Team</strong>
        <p style="margin-top: 4px; font-size: 0.85rem; color: var(--admin-res-text, rgba(255,255,255,0.7));">${safeEsc(review.admin_response)}</p>
      </div>
    ` : '';

    let editBtnHtml = '';
    if (currentUser && review.user_id === currentUser.id) {
      editBtnHtml = `<button type="button" onclick="openEditReviewForm('${review.id}', ${review.rating}, '${productId}')" style="background:none;border:none;color:var(--admin-res-text,#F891A5);font-size:0.75rem;cursor:pointer;margin-left:10px;text-decoration:underline;">Edit</button>`;
    }

    reviewEl.innerHTML = `
      <div class="review-header">
        <div class="review-rating">${starsHtml(review.rating)}</div>
        <span class="review-author">${safeEsc(review.nickname || review.reviewer_name || 'Anonymous')}</span>
        ${review.verified_purchase ? '<span class="verified-badge">Verified Purchase</span>' : ''}
        ${editBtnHtml}
      </div>
      ${review.title ? `<p class="review-title">${safeEsc(review.title)}</p>` : ''}
      ${review.body ? ((typeof reviewNeedsCollapse === 'function' && reviewNeedsCollapse(review.body))
        ? `<p class="review-body" data-collapsible="1">${safeEsc(reviewShort(review.body))}… </p><button type="button" class="review-more-btn" aria-expanded="false">View more</button>`
        : `<p class="review-body">${safeEsc(review.body)}</p>`) : ''}
      ${adminResponseHtml}
    `;
    content.appendChild(reviewEl);
    if (typeof reviewNeedsCollapse === 'function' && reviewNeedsCollapse(review.body)) {
      const _bodyEl = reviewEl.querySelector('.review-body[data-collapsible]');
      const _moreBtn = reviewEl.querySelector('.review-more-btn');
      if (_bodyEl && _moreBtn) {
        const _short = reviewShort(review.body) + '… ';
        let _expanded = false;
        _moreBtn.addEventListener('click', () => {
          _expanded = !_expanded;
          _bodyEl.textContent = _expanded ? review.body : _short; // textContent = safe, no re-escaping
          _moreBtn.textContent = _expanded ? 'View less' : 'View more';
          _moreBtn.setAttribute('aria-expanded', String(_expanded));
        });
      }
    }
  });

  // Always offer the modal when there's at least one review (guaranteed by the
  // early return above) — the "See Reviews" button — so the full list + any
  // photos/lightbox are always reachable, even with a single review. Reads
  // "View All N Reviews" when there's more than the 6 shown inline.
  {
    const moreBtn = document.createElement('button');
    moreBtn.className = 'more-reviews-btn';
    const _hasMore = currentProduct.reviews.length > displayReviews.length;
    moreBtn.textContent = _hasMore ? `View All ${currentProduct.reviews.length} Reviews` : 'See Reviews';
    moreBtn.onclick = () => openAllReviewsModal(currentProduct.id, currentProduct.id, currentProduct.title);
    content.appendChild(moreBtn);
  }
}

