// ACCORDION TOGGLE
// ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â
function toggleAccordion(header) {
  const body = header.nextElementSibling;
  const isOpen = header.classList.contains('open');

  // Toggle only the clicked column — the others keep their state, so any number
  // of columns can be open at the same time.
  if (isOpen) {
    // Collapse from the panel's real, current height so the ease plays out
    // on-screen. After opening, the cap is released to max-height:none (so
    // dynamic content can grow), so resolve the live height, pin it, force a
    // reflow, then drop to 0 — otherwise there's no concrete start value to
    // animate from and it just snaps shut.
    const current = getComputedStyle(body).maxHeight;
    body.style.maxHeight = (current === 'none' ? body.scrollHeight + 'px' : current);
    void body.offsetHeight; // reflow: lock in the start value
    body.style.maxHeight = '';
    header.classList.remove('open');
    header.setAttribute('aria-expanded', 'false');
  } else {
    // Expand to the EXACT content height so the curve finishes at the panel's
    // bottom edge. (The old code padded +3000px, so the easing completed far
    // below the fold — open looked abrupt and close spent most of its duration
    // collapsing the invisible buffer before snapping.) Once the open
    // transition ends, release the cap so review forms / "more reviews" can
    // grow freely without being clipped.
    header.classList.add('open');
    header.setAttribute('aria-expanded', 'true');
    body.style.maxHeight = body.scrollHeight + 'px';
    body.addEventListener('transitionend', function onEnd(e) {
      if (e.target !== body || e.propertyName !== 'max-height') return;
      body.removeEventListener('transitionend', onEnd);
      if (header.classList.contains('open')) body.style.maxHeight = 'none';
    });
  }
}

// ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â
// ADD TO CART
// ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â
function pulseBagTarget() {
  const target = document.getElementById('cart-btn');
  if (!target) return;
  target.classList.remove('bag-dip');
  void target.offsetWidth;
  target.classList.add('bag-dip');
  window.setTimeout(() => target.classList.remove('bag-dip'), 460);
}

function animateAddToBag(sourceEl, imageSrc) {
  // If the header was scrolled away, pop it back so the shopper sees the bag
  // update. When it was hidden, let it finish sliding in (~0.35s) BEFORE the bag
  // pulse, so the two happen in sequence rather than on top of each other.
  var wasHidden = (typeof window.zwRevealHeader === 'function') && window.zwRevealHeader();
  // Add-to-bag acknowledgment: the bag icon "drop-in dip" (it dips and
  // squashes as if the item landed in it). prefers-reduced-motion honored in CSS.
  if (wasHidden) window.setTimeout(pulseBagTarget, 380);
  else pulseBagTarget();
}

/* ── Related products ("More From Release 001") ─────────────────── */
async function loadRelatedProducts() {
  try {
    if (!window.sb || !currentProduct?.id) return;
    // Honour the Page Builder's Product tab — this block can be switched off or
    // removed there. Two different "no row" cases have to stay apart:
    //   config unreadable  -> hiccup, leave it visible (fail open; it's decorative)
    //   read fine, no row  -> the admin removed the block; it stays gone
    // Testing `row && row.on === false` treated both as "not configured" and
    // showed the block, so removing it — including emptying the layout to get a
    // bare product page — did nothing here. This is the only block product.html
    // renders itself; the rest come from storefront-features.js, which reads the
    // same layout literally.
    try {
      const cfg = await fetch('/api/product-page-config').then(r => r.ok ? r.json() : null).catch(() => null);
      if (cfg && Array.isArray(cfg.sections)) {
        const row = cfg.sections.find(s => s && s.id === 'more_from_release');
        if (!row || row.on === false) return;
      }
    } catch (_) {}
    const { data } = await window.sb
      .from('products')
      .select('id,title,current_price,product_images(image_url,sort_order)')
      .eq('status', 'Live')
      .neq('id', currentProduct.id)
      .limit(3);
    const grid = document.getElementById('related-grid');
    const section = document.getElementById('related-products');
    if (!grid || !section || !data?.length) return;
    const esc = v => String(v == null ? '' : v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
    const slugOf = t => String(t||'').replace(/^zuwera\s+/i,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'') || 'product';
    grid.innerHTML = data.map(p => {
      const imgs = (p.product_images || []).slice().sort((a,b)=>(a.sort_order??0)-(b.sort_order??0));
      const img = imgs[0]?.image_url || '';
      const href = `/product/${slugOf(p.title)}?id=${p.id}`;
      const price = parseFloat(p.current_price);
      return `<a href="${esc(href)}" class="pcard" style="display:block;text-decoration:none;color:inherit;border:1px solid var(--c08)">
        <div class="pcard-img" style="aspect-ratio:4/5;overflow:hidden;background:rgb(var(--fg-rgb) / 3%)">
          ${img ? `<img src="${esc(typeof window.optimizeImage==='function'?window.optimizeImage(img,520):img)}" alt="${esc(p.title)}" loading="lazy" style="width:100%;height:100%;object-fit:cover;display:block">` : ''}
        </div>
        <div class="pcard-info" style="padding:1rem 1.1rem">
          <p class="pcard-name" style="margin:0 0 .25rem">${esc(p.title)}</p>
          ${!Number.isNaN(price) && price > 0 ? `<p class="pcard-price" style="margin:0">$${price.toFixed(2)}</p>` : ''}
        </div>
      </a>`;
    }).join('');
    section.style.display = '';
  } catch (_) { /* related products are decorative — never break the page */ }
}

/* ── Back-in-stock notify ────────────────────────────────────────── */
let _restockSize = null;

function openRestockPanel(size) {
  // Back-in-stock master switch (Admin → Feature Flags → feature_back_in_stock).
  // Permissive: only suppressed when EXPLICITLY disabled, so the prompt keeps
  // working if flags haven't loaded yet or the toggle was never touched.
  try {
    const _bis = window.__zwFlags && window.__zwFlags.feature_back_in_stock;
    if (_bis && _bis.enabled === false) return;
  } catch (_) {}
  _restockSize = size;
  const panel = document.getElementById('restock-panel');
  const label = document.getElementById('restock-label');
  const msg = document.getElementById('restock-msg');
  const emailEl = document.getElementById('restock-email');
  if (!panel) return;
  if (label) ZWStock.applyMsg(label, 'restockPrompt', { size });
  if (msg) { msg.textContent = ''; msg.style.color = ''; }
  // Prefill from the signed-in session when available.
  if (emailEl && !emailEl.value.trim()) {
    try {
      const u = window.__zwSessionUser;
      if (u?.email) emailEl.value = u.email;
      else if (window.sb) window.sb.auth.getSession().then(r => {
        const e = r?.data?.session?.user?.email;
        if (e && emailEl && !emailEl.value.trim()) emailEl.value = e;
      }).catch(() => {});
    } catch (_) {}
  }
  panel.style.display = 'block';
  document.getElementById('restock-email')?.focus({ preventScroll: true });
}

function hideRestockPanel() {
  const panel = document.getElementById('restock-panel');
  if (panel) panel.style.display = 'none';
  _restockSize = null;
}

window.submitRestockRequest = async function() {
  const emailEl = document.getElementById('restock-email');
  const msg = document.getElementById('restock-msg');
  const btn = document.getElementById('restock-submit');
  const email = (emailEl?.value || '').trim();
  if (!_restockSize || !currentProduct?.id) return;
  if (!email || !email.includes('@')) {
    if (msg) { msg.textContent = 'Enter a valid email.'; msg.style.color = 'var(--red,#dc2626)'; }
    return;
  }
  if (btn) { btn.disabled = true; btn.textContent = '…'; }
  try {
    const { error } = await window.sb.from('restock_requests').insert({
      product_id: currentProduct.id,
      size: _restockSize,
      color_name: (typeof selectedColor !== 'undefined' && selectedColor?.color_name) || null,
      email,
    });
    if (error) {
      // Unique violation = already registered; everything else surfaces.
      if (String(error.code) === '23505') {
        if (msg) ZWStock.applyMsg(msg, 'restockAlready');
      } else {
        throw error;
      }
    } else {
      if (msg) ZWStock.applyMsg(msg, 'restockSuccess', { size: _restockSize });
    }
    if (btn) { btn.textContent = 'Notify Me'; btn.disabled = false; }
  } catch (e) {
    if (msg) ZWStock.applyMsg(msg, 'restockFailed');
    if (btn) { btn.textContent = 'Notify Me'; btn.disabled = false; }
  }
};

function addToCart() {
  // Early-access gate: when enabled by the admin and within the window,
  // only signed-in members can add to bag.
  if (typeof window.zwEarlyAccessBlocked === 'function' && window.zwEarlyAccessBlocked()) {
    if (typeof showToast === 'function') showToast('Early access is for members — sign in to shop first.');
    if (typeof openAuthModal === 'function') openAuthModal('signin');
    return;
  }
  /* A gift card has no size, so there is nothing to ask for and nothing to
     refuse over. It went into the bag as a MEDIUM before this — the page falls
     back to XS–3XL when a product has no rows in product_sizes, so the picker
     invented seven sizes and the shopper picked one of them.

     The empty string is deliberate rather than 'One Size': the till's stock
     check is `if (itemSize && limitToStock)`, so no size means no check at all,
     and the order line then says nothing about a size instead of claiming a
     medium on the record and in the confirmation email. */
  if (!selectedSize && !isGiftCardProduct()) {
    alert('Please select a size');
    return;
  }

  /* A gift card with nowhere to go. Refused here rather than at the till, and
     beside the field rather than as a toast, because every one of these is a
     box on screen the shopper can see is empty. Literally the same function the
     quick-add panel calls — it belongs to the module, not to this page. */
  if (isGiftCardProduct() && _gcBuy && _gcBuy.problem()) return;

  const regularPrice = getRegularProductPrice(currentProduct);
  const memberPrice = getMemberProductPrice(currentProduct);
  const effectivePrice = getEffectiveProductPrice(currentProduct);

  const stockQty = currentProduct.inventory.length
    ? sizeStockForColor(selectedSize, (selectedColor && selectedColor.color_name) || null)
    : null;

  const cartItem = {
    productId: currentProduct.id,
    sku: selectedColorSku || currentProduct.sku,
    title: currentProduct.title,
    /* Empty for a gift card, not a made-up size — see addToCart above. */
    size: isGiftCardProduct() ? '' : selectedSize,
    colorName: selectedColor?.color_name || 'Standard',
    colorHex: selectedColor?.hex_color || '',
    regularPrice,
    memberPrice,
    /* The displayed price, which for a buyer-priced gift card is the amount
       they chose. It has to be: the till refuses to charge more than the cart
       says it showed, so a line still claiming $50 against a $73 card would be
       rejected as a price change — the guard doing exactly its job against the
       one case where the higher figure is the shopper's own instruction. */
    price: effectivePrice,
    image: currentProduct.images[0]?.image_url || '',
    /* Carried so the bag and the checkout can tell what they are holding. The
       till reads it off the catalogue and always will — this copy decides
       nothing, it only stops the browser drawing a shipping line and a tax line
       against a code in an email. */
    giftCardCents: Number(currentProduct.gift_card_cents) || 0,
    /* The buyer's figure, when they chose one. The SERVER turns this single
       input into both the price and the face value — see the note in
       _cart-pricing.js. Sending a price and a face value separately is the one
       thing that would make a customer-named amount unsafe, so this file sends
       neither: it sends the amount, once. */
    weightLb: parseFloat(currentProduct.shipping_weight_lb) || 0.5,
    stockQty,
    quantity: 1
  };

  /* The amount, the recipient, the zero weight and the empty size — all from
     the module, so this page and the quick-add panel put an identical line in
     the bag. It sends the chosen amount and never a face value beside it: a
     price and a face value sent separately is the whole hole. */
  if (isGiftCardProduct() && _gcBuy) _gcBuy.applyTo(cartItem);

  let cart = JSON.parse(localStorage.getItem('cart')) || [];

  // Check if item already in cart
  /* Product, size and colour used to be the whole list, and it was the whole
     list for as long as those three decided the price. A buyer-named amount
     broke it: a $25 card and a $300 card are the same product, the same (empty)
     size and the same colour, so adding the second found the first and made two
     of it -- the shopper asked for $300 and got a second $25. */
  const existingIdx = cart.findIndex(
    item => item.productId === cartItem.productId &&
             item.size === cartItem.size &&
             item.colorName === cartItem.colorName &&
             (Number(item.customAmountCents) || 0) === (Number(cartItem.customAmountCents) || 0)
             /* And who it is for. Two $50 cards for two different people are
                not two of one card, and merging them sends both to whoever was
                typed first — with the second recipient silently dropped. */
             && JSON.stringify(item.giftCardTo || null) === JSON.stringify(cartItem.giftCardTo || null)
  );

  /* How many more of THIS variant may be added, not how many exist. Saying
     "Only 1 in stock" to someone who already has that 1 in their bag describes
     the shelf rather than their options.

     Counted by ZWStock so the match is the one the bag and checkout use — the
     old comparison here was product+size and ignored colour, so a bagged Yellow
     could block adding a Tennesee that was fully stocked.

     Both refusals stop the same action and mean opposite things, so which one
     is said comes from .soldOut — the shelf — and never from the count. The
     count is zero in both cases, which is how the product page came to announce
     a sell-out because of what was in the shopper's own bag. */
  if (window.ZWStock && ZWStock.availability) {
    const avail = ZWStock.availability(stockQty, cartItem, cart);
    if (!avail.canAdd) {
      showToast(avail.soldOut
        ? ZWStock.msg('soldOutItem', { title: currentProduct.title, size: cartItem.size })
        : ZWStock.msg('maxedOut', { count: avail.inBag }));
      return;
    }
  }

  if (existingIdx > -1) {
    cart[existingIdx].quantity += 1;
    cart[existingIdx].stockQty = stockQty;
  } else {
    cart.push(cartItem);
  }

  localStorage.setItem('cart', JSON.stringify(cart));
  loadCartCount();

  if (typeof gtag === 'function') {
    gtag('event', 'add_to_cart', {
      currency: 'USD',
      value: effectivePrice,
      items: [{
        item_id: currentProduct.id,
        item_name: currentProduct.title,
        price: effectivePrice,
        quantity: 1
      }]
    });
  }
  zwTrack('add_to_cart', {
    product_id:    currentProduct.id,
    product_name:  currentProduct.title,
    price:         effectivePrice,
    regular_price: regularPrice,
    member_price:  memberPrice,
    size:          selectedSize,
    color:         selectedColor?.color_name || 'Standard',
    currency:      'USD',
  });
  if (window.zwPixel) zwPixel.addToCart({
    productId: currentProduct.id,
    title:     currentProduct.title,
    price:     effectivePrice,
    quantity:  1
  });

  // Show success toast
  animateAddToBag(document.getElementById('mainImage') || document.getElementById('addToCartBtn'), cartItem.image);
  showToast('Added to bag');
}

