// SHOW TOAST
// ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â
function showToast(message) {
  const t = document.getElementById('toast');
  if (!t) return;
  t.textContent = message;
  t.classList.add('on');
  clearTimeout(t._toastTimer);
  t._toastTimer = setTimeout(() => t.classList.remove('on'), 2600);
}

// ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â
// ERROR HANDLING
// ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â
function showError(message) {
  document.getElementById('loadingState').classList.add('hidden');
  document.getElementById('errorState').classList.remove('hidden');
  document.getElementById('errorMessage').textContent = message;
}

async function loadProductReviewsForModal() {
  const cachedReviews = Array.isArray(currentProduct?.reviews) ? currentProduct.reviews : [];
  if (cachedReviews.length || !currentProduct?.id || typeof loadReviews !== 'function') {
    return cachedReviews;
  }

  let timerId = null;
  try {
    return await Promise.race([
      loadReviews(currentProduct.id),
      new Promise((_, reject) => {
        timerId = setTimeout(() => reject(new Error('Timed out loading size and fit reviews.')), 8000);
      })
    ]);
  } finally {
    if (timerId) clearTimeout(timerId);
  }
}

function reviewHasFitSignals(review) {
  return Boolean(
    review &&
    (
      review.fit_rating != null ||
      review.comfort_rating != null ||
      typeof review.recommend === 'boolean'
    )
  );
}

function escapeSizeFitHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function generateHatFitModalHtml(activeRow, allRows = [], fitReviews = []) {
  if (!activeRow) {
    return '<p class="review-modal-message">Could not find hat sizing for this product right now.</p>';
  }

  const _isLight = document.body.classList.contains('light-mode');
  const _cardBorder = _isLight ? 'rgba(9,9,11,0.08)' : 'var(--c08)';
  const _cardText = _isLight ? 'rgba(9,9,11,0.7)' : 'rgb(var(--fg-rgb) / 72%)';
  const _inactiveBadgeBg = _isLight ? 'rgba(9,9,11,0.03)' : 'rgb(var(--fg-rgb) / 3%)';
  const _inactiveBadgeBorder = _isLight ? 'rgba(9,9,11,0.08)' : 'var(--c08)';

  const sizeLabel = escapeSizeFitHtml(formatProductSizeLabel(activeRow.size_label || 'One Size'));
  const circumference = [
    activeRow.head_circ_in ? `${escapeSizeFitHtml(activeRow.head_circ_in)} in` : '',
    activeRow.head_circ_cm ? `${escapeSizeFitHtml(activeRow.head_circ_cm)} cm` : ''
  ].filter(Boolean).join(' / ');

  const rowsHtml = allRows.map((row) => {
    const isActive = normalizeSizeLabel(row?.size_label) === normalizeSizeLabel(activeRow.size_label);
    const badgeStyle = isActive
      ? 'background: rgba(248,145,165,0.14); border-color: rgba(248,145,165,0.35);'
      : `background: ${_inactiveBadgeBg}; border-color: ${_inactiveBadgeBorder};`;
    const label = escapeSizeFitHtml(formatProductSizeLabel(row?.size_label || ''));
    const measurements = [
      row?.head_circ_in ? `${escapeSizeFitHtml(row.head_circ_in)} in` : '',
      row?.head_circ_cm ? `${escapeSizeFitHtml(row.head_circ_cm)} cm` : ''
    ].filter(Boolean).join(' / ');
    return `
      <div class="review-modal-card" style="padding: 1rem 0; border-bottom: 1px solid ${_cardBorder};">
        <div class="review-card-header" style="display:flex; justify-content:space-between; align-items:flex-start; gap:12px;">
          <div>
            <div class="review-card-title" style="font-size:0.95rem; font-weight:600; margin-bottom:4px;">${label}</div>
            <div class="review-card-body" style="font-size:0.88rem; color: ${_cardText};">${measurements || 'Measurement not available'}</div>
          </div>
          <span class="review-card-badge" style="padding:4px 8px; border:1px solid ${_inactiveBadgeBorder}; border-radius:999px; font-size:0.72rem; ${badgeStyle}">${isActive ? 'Selected' : 'Guide'}</span>
        </div>
      </div>
    `;
  }).join('');

  const communityBlock = fitReviews.length && typeof generateReviewSummaryHtml === 'function'
    ? `
      <div style="margin-top: 1.5rem;">
        <p class="review-modal-eyebrow" style="margin-bottom:0.6rem;">Community Fit</p>
        ${generateReviewSummaryHtml(fitReviews)}
      </div>
    `
    : '<p class="review-modal-message" style="margin-top: 1.25rem;">No community fit ratings have been submitted yet, so this view is using the saved hat size guide.</p>';

  return `
    <div class="review-summary-box">
      <div class="rs-left">
        <div class="rs-rating">${sizeLabel}</div>
        <div class="rs-count">Current size focus</div>
        <div class="rs-count">Head Circumference</div>
      </div>
      <div class="rs-right">
        <div class="rs-metric">
          <div class="rs-metric-title">Head circumference for this size</div>
          <div class="rs-metric-subtitle">${circumference || 'Measurement not available'}</div>
        </div>
        <div class="rs-recommend">
          <div class="rs-metric-title">Guide sizes available</div>
          <div class="rs-metric-subtitle">${allRows.length} size option${allRows.length !== 1 ? 's' : ''}</div>
        </div>
      </div>
    </div>
    ${communityBlock}
    <div style="margin-top: 1.5rem;">
      ${rowsHtml}
    </div>
  `;
}

window.openSizeFitModal = async function() {
  const modal = document.getElementById('size-fit-modal');
  const content = document.getElementById('size-fit-summary-content');
  if (!modal || !content) return;

  const title = modal.querySelector('#size-fit-title');
  const eyebrow = modal.querySelector('.review-modal-eyebrow');
  const copy = modal.querySelector('.review-modal-copy');
  const context = getSizeGuideContext();
  const isHatProduct = context?.calcCategory === 'hats';

  if (title) title.textContent = 'Size & Fit';
  if (eyebrow) eyebrow.textContent = 'Community Fit';
  if (copy) copy.textContent = 'Live fit notes pulled from recent reviews for this specific piece.';

  content.innerHTML = '<p class="review-modal-message">Loading fit ratings...</p>';
  modal.classList.add('open');
  // Force the bottom-sheet layout on mobile inline — beats any stacked modal CSS
  // that was still centring it. Desktop stays a centred dialog. Uses the
  // site-wide 900px modal breakpoint (was 600px, which left tablet widths
  // 601-900px as a floating centred card).
  const _sfBox = modal.querySelector('.review-dialog');
  if (window.matchMedia('(max-width:900px)').matches) {
    modal.style.setProperty('align-items', 'flex-end', 'important');
    modal.style.setProperty('justify-content', 'center', 'important');
    if (_sfBox) {
      _sfBox.style.setProperty('width', '100%', 'important');
      _sfBox.style.setProperty('max-width', '100%', 'important');
      _sfBox.style.setProperty('border-radius', '1.25rem 1.25rem 0 0', 'important');
    }
  } else {
    modal.style.removeProperty('align-items');
    modal.style.removeProperty('justify-content');
    if (_sfBox) { _sfBox.style.removeProperty('width'); _sfBox.style.removeProperty('max-width'); _sfBox.style.removeProperty('border-radius'); }
  }
  // Clear/transparent backdrop, like every other modal on the site.
  modal.style.setProperty('background', 'rgba(var(--zw-mbd-rgb),var(--zw-mbd-a))', 'important');
  modal.style.setProperty('backdrop-filter', 'var(--zw-mbd-blur,none)', 'important');
  modal.style.setProperty('-webkit-backdrop-filter', 'var(--zw-mbd-blur,none)', 'important');
  // Defer the scroll lock to modal-lock.js (position:fixed + scroll compensation)
  // instead of a raw overflow:hidden — the dual lock shifted the page up on open.
  if (window.ZWModalScrollLock) window.ZWModalScrollLock.refresh(); else document.body.style.overflow = 'hidden';

  try {
    const reviews = await loadProductReviewsForModal();
    if (currentProduct) currentProduct.reviews = Array.isArray(reviews) ? reviews : [];

    const fitReviews = Array.isArray(reviews)
      ? reviews.filter(reviewHasFitSignals)
      : [];

    if (!fitReviews.length) {
      content.innerHTML = isHatProduct
        ? '<p class="review-modal-message">No size or comfort ratings have been submitted yet. Use View Size Guide for head-circumference measurements.</p>'
        : '<p class="review-modal-message">No size or comfort ratings have been submitted yet.</p>';
      return;
    }

    content.innerHTML = typeof generateReviewSummaryHtml === 'function'
      ? generateReviewSummaryHtml(fitReviews)
      : '<p class="review-modal-message">Fit ratings are available, but the summary view could not render.</p>';
  } catch (error) {
    console.error('Size & fit modal failed:', error);
    content.innerHTML = '<p class="review-modal-message">Could not load fit ratings right now.</p>';
  }
};

let _sizeGuideDocumentHtml = null;

async function getSizeGuideDocumentHtml() {
  if (_sizeGuideDocumentHtml) return _sizeGuideDocumentHtml;
  // Default cache mode (not no-store): HTML is served no-cache/must-revalidate,
  // so the browser revalidates and gets a 304 when unchanged instead of
  // re-downloading the full document on every first modal open.
  const response = await fetch('/sizeguide.html');
  if (!response.ok) throw new Error('Failed to load size guide.');
  _sizeGuideDocumentHtml = await response.text();
  return _sizeGuideDocumentHtml;
}

function buildSizeGuideSrcdoc(sourceHtml, params) {
  const serializedParams = JSON.stringify(params || {}).replace(/</g, '\\u003c');
  /* THE GUIDE INHERITS THE PAGE'S THEME RATHER THAN WORKING IT OUT AGAIN.
     It is a separate document, so it was resolving the theme for itself from
     localStorage — and a srcdoc frame does not always get to read localStorage,
     which is how the size guide could open dark over a light product page. Two
     documents answering the same question from different evidence.
     The parent already knows; it says so. */
  const themeNow = (function () {
    try {
      if (window.ZWTheme && window.ZWTheme.current) return String(window.ZWTheme.current() || '');
    } catch (_) {}
    return String(document.documentElement.getAttribute('data-zw-base') || '');
  }());
  const baseNow = document.body.classList.contains('super-light-mode') ? 'super-light'
    : document.body.classList.contains('light-mode') ? 'light' : 'dark';
  const injectedHead = `<base href="${window.location.origin}/"><script>window.__ZW_SIZEGUIDE_PARAMS__=${serializedParams};window.__ZW_SIZEGUIDE_EMBED__=true;window.__ZW_SIZEGUIDE_THEME__=${JSON.stringify({ id: themeNow, base: baseNow })};<\/script>`;
  // Strip scripts the embedded guide doesn't use — analytics/pixels, favicon,
  // the mobile nav, and modal-lock — so the iframe boots faster on every open
  // (fewer requests, and no third-party network calls from inside the modal).
  const html = sourceHtml.replace(
    /<script\b[^>]*\bsrc="[^"]*\/?(?:meta-pixel|google-tag|posthog-init|favicon-utils|mobile-menu|modal-lock)\.js[^"]*"[^>]*><\/script>\s*/gi,
    ''
  );
  return html.includes('<head>')
    ? html.replace('<head>', `<head>${injectedHead}`)
    : injectedHead + html;
}


let _sizeGuideModalResizeObserver = null;
let _sizeGuideModalLoadToken = 0;
let _sizeGuideBooted = false;        // iframe has the guide document loaded + ready
let _sizeGuideBootedKey = '';        // non-size context the iframe was booted with
let _sizeGuideBootedSize = null;     // size currently reflected in the booted guide
let _sizeGuideBootPromise = null;    // in-flight boot, so prewarm + open don't double-boot

function teardownSizeGuideModalAutoHeight() {
  if (_sizeGuideModalResizeObserver) {
    try { _sizeGuideModalResizeObserver.disconnect(); } catch(e) {}
    _sizeGuideModalResizeObserver = null;
  }
}

function buildSizeGuideParams() {
  const context = getSizeGuideContext();
  const params = {};
  if (context?.gender) params.gender = context.gender;
  if (context?.categoryLabel) params.category = context.categoryLabel;
  if (context?.calcCategory) params.guide = context.calcCategory;
  if (context?.tabId) params.tab = context.tabId;
  if (context?.focused) params.focused = true;
  if (currentProduct?.id) params.id = currentProduct.id;
  if (selectedSize) params.size = selectedSize;
  return params;
}

// Everything in the context except the selected size — fixed for a product page,
// so a booted iframe can be reused as long as this key matches.
function sizeGuideContextKey(params) {
  const p = Object.assign({}, params);
  delete p.size;
  return JSON.stringify(p);
}

// Measure the embedded guide and keep its height synced. Shared by boot + reuse.
function attachSizeGuideAutoHeight(iframe) {
  const doc = iframe.contentDocument;
  if (!doc?.body) return;
  const syncH = () => {
    const b = iframe.contentDocument?.body;
    if (!b) return;
    // Body content height only — documentElement.scrollHeight reports at least
    // the iframe's own height, which would make the frame only ever grow.
    const h = Math.max(b.scrollHeight || 0, b.offsetHeight || 0);
    if (h > 0) iframe.style.height = h + 'px';
  };
  teardownSizeGuideModalAutoHeight();
  syncH();
  if (typeof ResizeObserver === 'function' && doc.body) {
    _sizeGuideModalResizeObserver = new ResizeObserver(syncH);
    _sizeGuideModalResizeObserver.observe(doc.body);
    if (doc.documentElement) _sizeGuideModalResizeObserver.observe(doc.documentElement);
  }
  setTimeout(syncH, 0); setTimeout(syncH, 120); setTimeout(syncH, 360);
}

function revealSizeGuideIframe(iframe, loading) {
  iframe.hidden = false;
  iframe.style.visibility = 'hidden';   // in layout but unpainted, so we can measure
  attachSizeGuideAutoHeight(iframe);
  iframe.style.visibility = '';
  if (loading) loading.hidden = true;
}

// Boot the guide document into the iframe exactly once (shared by prewarm and
// open). Resolves as soon as the body is parsed, not on full sub-resource load.
function ensureSizeGuideBooted(iframe, params) {
  if (_sizeGuideBooted) return Promise.resolve(true);
  if (_sizeGuideBootPromise) return _sizeGuideBootPromise;
  _sizeGuideBootPromise = (async () => {
    let ok = false;
    try {
      const sourceHtml = await getSizeGuideDocumentHtml();
      ok = await new Promise((resolve) => {
        let settled = false;
        const settle = (v) => { if (settled) return; settled = true; iframe.onload = null; resolve(v); };
        const ready = () => {
          // Require the REAL guide content (not an empty about:blank). Matters
          // when prewarming inside a still-hidden modal, where some browsers
          // defer the srcdoc load — we must not mark an empty iframe as booted.
          const doc = iframe.contentDocument;
          if (doc && doc.body && doc.querySelector('.page-wrap')) settle(true);
        };
        iframe.onload = ready;
        iframe.srcdoc = buildSizeGuideSrcdoc(sourceHtml, params);
        setTimeout(ready, 250);
        setTimeout(ready, 900);
        setTimeout(() => settle(false), 4000);   // give up — caller boots on demand
      });
      if (ok) {
        _sizeGuideBooted = true;
        _sizeGuideBootedKey = sizeGuideContextKey(params);
        _sizeGuideBootedSize = params.size || null;
      }
    } finally {
      _sizeGuideBootPromise = null;
    }
    return ok;
  })();
  return _sizeGuideBootPromise;
}

// ---- Find My Size quick calculator (native modal, bottom sheet on mobile) ----
function fsToggleUnit(btn) {
  const group = btn.parentElement;
  if (!group) return;
  group.querySelectorAll('.fs-unit').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
}
function fsActiveUnit(field) {
  const btn = document.querySelector('#find-size-modal .fs-toggles[data-field="' + field + '"] .fs-unit.active');
  return btn ? btn.getAttribute('data-unit') : null;
}
// Weight-driven size buckets with a ±1 nudge for a notably tall/short frame —
// mirrors sizeguide.html's findApparelSizeByHeightWeight so both agree.
function fsRecommendSize(gender, heightIn, weightLbs) {
  const scale = gender === 'women'
    ? [['XXS',105],['XS',120],['S',140],['M',160],['L',185],['XL',215],['2XL',245],['3XL',Infinity]]
    : [['XS',135],['S',155],['M',180],['L',205],['XL',235],['2XL',265],['3XL',Infinity]];
  let idx = scale.findIndex(([, mx]) => weightLbs <= mx);
  if (idx < 0) idx = scale.length - 1;
  const avg = gender === 'women' ? 65 : 70;
  if (heightIn >= avg + 5 && idx < scale.length - 1) idx += 1;
  else if (heightIn <= avg - 5 && idx > 0) idx -= 1;
  return scale[idx][0];
}
function openFindSizeModal() {
  const m = document.getElementById('find-size-modal');
  if (!m) return;
  const err = document.getElementById('fs-error'); if (err) err.textContent = '';
  const res = document.getElementById('fs-result'); if (res) res.hidden = true;
  const isSheet = window.matchMedia && window.matchMedia('(max-width:900px)').matches;
  const box = m.querySelector('.fs-box');
  // Style the box BEFORE it's shown (no flash of the boxy CSS version), all via
  // INLINE !important since the page cascade kept overriding stylesheet rules.
  // Full width like the other sheets; start off-screen for a clean slide-up (the
  // base .mbox `animation:modalIn` nudge fought the sheet motion and looked weird).
  if (isSheet && box) {
    box.style.setProperty('position', 'fixed', 'important');   // viewport-anchored — never floats
    box.style.setProperty('left', '0', 'important');
    box.style.setProperty('right', '0', 'important');
    box.style.setProperty('bottom', '0', 'important');
    box.style.setProperty('top', 'auto', 'important');
    box.style.setProperty('width', 'auto', 'important');
    box.style.setProperty('max-width', 'none', 'important');
    box.style.setProperty('margin', '0', 'important');
    box.style.setProperty('border', 'none', 'important');
    box.style.setProperty('border-radius', '24px 24px 0 0', 'important');
    box.style.setProperty('overflow', 'auto', 'important');
    box.style.setProperty('box-shadow', '0 -8px 40px rgba(0,0,0,.28)', 'important');
    box.style.setProperty('animation', 'none', 'important');
    box.style.setProperty('transition', 'none', 'important');
    box.style.setProperty('transform', 'translateY(100%)', 'important');
    m.style.setProperty('transition', 'background .28s ease, backdrop-filter .28s ease', 'important');
    m.style.setProperty('background', 'rgba(var(--zw-mbd-rgb),0)', 'important');   // fade from transparent
  }
  m.classList.add('open');
  m.setAttribute('aria-hidden', 'false');
  if (isSheet && box) {
    requestAnimationFrame(() => {
      // Fade in the admin modal-backdrop scrim (not a hardcoded dim) — inline so it
      // beats the page cascade, and follows the Dim/Blur/Frost/None + intensity setting.
      m.style.setProperty('background', 'rgba(var(--zw-mbd-rgb),var(--zw-mbd-a))', 'important');
      m.style.setProperty('backdrop-filter', 'var(--zw-mbd-blur,none)', 'important');
      m.style.setProperty('-webkit-backdrop-filter', 'var(--zw-mbd-blur,none)', 'important');
      requestAnimationFrame(() => {
        box.style.setProperty('transition', 'transform .4s cubic-bezier(.32,.72,0,1)', 'important');
        box.style.setProperty('transform', 'translateY(0)', 'important');   // slide up
      });
    });
  } else {
    // Desktop: apply the admin scrim directly (inline, !important) so the backdrop is
    // guaranteed — don't depend on the clearBackdrop MutationObserver having fired.
    m.style.setProperty('background', 'rgba(var(--zw-mbd-rgb),var(--zw-mbd-a))', 'important');
    m.style.setProperty('backdrop-filter', 'var(--zw-mbd-blur,none)', 'important');
    m.style.setProperty('-webkit-backdrop-filter', 'var(--zw-mbd-blur,none)', 'important');
  }
  if (window.ZWModalScrollLock) window.ZWModalScrollLock.refresh(); else document.body.style.overflow = 'hidden';
  setTimeout(() => { const h = document.getElementById('fs-height'); if (h) h.focus(); }, 60);
}
window.openFindSizeModal = openFindSizeModal;
function closeFindSizeModal() {
  const m = document.getElementById('find-size-modal');
  if (!m) return;
  const box = m.querySelector('.fs-box');
  const isSheet = box && window.matchMedia && window.matchMedia('(max-width:900px)').matches && m.classList.contains('open');
  const finish = () => {
    m.classList.remove('open');
    m.style.removeProperty('background');
    m.style.removeProperty('transition');
    if (box) { box.style.removeProperty('transform'); box.style.removeProperty('transition'); }
    m.setAttribute('aria-hidden', 'true');
    if (!document.querySelector('.modal.open')) {
      if (window.ZWModalScrollLock) window.ZWModalScrollLock.refresh(); else document.body.style.overflow = '';
    }
  };
  if (isSheet) {
    m.style.setProperty('background', 'rgba(9,9,11,0)', 'important');        // fade scrim out
    box.style.setProperty('transition', 'transform .26s cubic-bezier(.32,.72,0,1)', 'important');
    box.style.setProperty('transform', 'translateY(100%)', 'important');     // slide down
    setTimeout(finish, 240);
  } else {
    finish();
  }
}
window.closeFindSizeModal = closeFindSizeModal;
// If the viewport changes (rotation) while the sheet is open, re-assert its
// bottom anchor so it can't end up floating mid-screen.
window.addEventListener('resize', function () {
  const m = document.getElementById('find-size-modal');
  if (!m || !m.classList.contains('open')) return;
  const box = m.querySelector('.fs-box');
  if (box && window.matchMedia && window.matchMedia('(max-width:900px)').matches) {
    box.style.setProperty('position', 'fixed', 'important');
    box.style.setProperty('left', '0', 'important');
    box.style.setProperty('right', '0', 'important');
    box.style.setProperty('bottom', '0', 'important');
    box.style.setProperty('top', 'auto', 'important');
    box.style.setProperty('transform', 'translateY(0)', 'important');
  }
});
// iOS Safari keeps a zoomed-in VISUAL VIEWPORT after rotating landscape → portrait
// (text-size-adjust:100% is set, so it's the scale, not text inflation). Fix:
// momentarily pin maximum-scale so Safari re-fits to the new width, then release
// so pinch-zoom still works. `orientationchange` fires BEFORE the layout settles,
// so also react to the resize that follows a real WIDTH change (rotation) — not to
// the keyboard opening (which only changes height).
(function fixOrientationZoom() {
  var vp = document.querySelector('meta[name="viewport"]');
  if (!vp) return;
  var base = vp.getAttribute('content').replace(/\s*,?\s*maximum-scale=[^,]*/gi, '');
  var lastW = window.innerWidth, t;
  function refit() {
    clearTimeout(t);
    vp.setAttribute('content', base + ', maximum-scale=1');
    t = setTimeout(function () { vp.setAttribute('content', base); }, 600);
  }
  window.addEventListener('orientationchange', function () { setTimeout(refit, 60); });
  window.addEventListener('resize', function () {
    if (Math.abs(window.innerWidth - lastW) > 60) { lastW = window.innerWidth; refit(); }
  });
})();
function runFindSize() {
  const err = document.getElementById('fs-error');
  const res = document.getElementById('fs-result');
  err.textContent = ''; res.hidden = true;
  const rawH = parseFloat(document.getElementById('fs-height').value);
  const rawW = parseFloat(document.getElementById('fs-weight').value);
  if (!(rawH > 0) || !(rawW > 0)) { err.textContent = 'Please enter a valid height and weight.'; return; }
  const hUnit = fsActiveUnit('height'), wUnit = fsActiveUnit('weight');
  const heightIn = hUnit === 'cm' ? rawH / 2.54 : rawH;
  const weightLbs = wUnit === 'kg' ? rawW * 2.2046 : rawW;
  if (heightIn < 48 || heightIn > 84) { err.textContent = hUnit === 'cm' ? 'Enter a height between 122 and 213 cm.' : 'Enter a height between 48 and 84 inches.'; return; }
  if (weightLbs < 70 || weightLbs > 400) { err.textContent = wUnit === 'kg' ? 'Enter a weight between 32 and 181 kg.' : 'Enter a weight between 70 and 400 lb.'; return; }
  let gender = (typeof getSizeGuideContext === 'function' && getSizeGuideContext() || {}).gender;
  if (gender !== 'women' && gender !== 'men') gender = 'men';
  const size = fsRecommendSize(gender, heightIn, weightLbs);
  const hDisp = hUnit === 'cm' ? rawH + ' cm' : rawH + '"';
  const wDisp = wUnit === 'kg' ? rawW + ' kg' : rawW + ' lb';
  document.getElementById('fs-result-size').textContent = size;
  document.getElementById('fs-result-text').textContent =
    'Based on height ' + hDisp + ' and weight ' + wDisp + '. A starting point — size up for a looser fit, or check the full chart if you’re between sizes.';
  res.hidden = false;
}
function fsOpenFullGuide() {
  closeFindSizeModal();
  if (window.openSizeGuideModal) window.openSizeGuideModal();
  return false;
}

window.openSizeGuideModal = async function() {
  if (syncSizeGuideVisibility(getAvailableProductSizes())) return;
  const modal   = document.getElementById('size-guide-modal');
  const iframe  = document.getElementById('size-guide-modal-iframe');
  const loading = document.getElementById('size-guide-modal-loading');
  if (!modal || !iframe) return;

  const context = getSizeGuideContext();
  syncSizeGuideModalMeta(context);
  const params = buildSizeGuideParams();

  modal.classList.add('open');
  modal.style.setProperty('background', 'rgba(var(--zw-mbd-rgb),var(--zw-mbd-a))', 'important');
  modal.style.setProperty('backdrop-filter', 'var(--zw-mbd-blur,none)', 'important');
  modal.style.setProperty('-webkit-backdrop-filter', 'var(--zw-mbd-blur,none)', 'important');
  // Defer the scroll lock to modal-lock.js (position:fixed + scroll compensation)
  // instead of a raw overflow:hidden — the dual lock shifted the page up on open.
  if (window.ZWModalScrollLock) window.ZWModalScrollLock.refresh(); else document.body.style.overflow = 'hidden';

  // Warm path: the iframe is already booted for this product — re-sync only the
  // selected size (if it changed) and reveal. No rebuild, so it opens instantly.
  const win = iframe.contentWindow;
  if (_sizeGuideBooted
      && iframe.contentDocument?.body
      && sizeGuideContextKey(params) === _sizeGuideBootedKey
      && typeof win?.__zwApplyGuideSize === 'function') {
    try {
      const size = params.size || null;
      if (size !== _sizeGuideBootedSize) { win.__zwApplyGuideSize(size); _sizeGuideBootedSize = size; }
      _sizeGuideModalLoadToken++;   // invalidate any stale cold-boot reveal
      revealSizeGuideIframe(iframe, loading);
      return;
    } catch (e) { _sizeGuideBooted = false; _sizeGuideBootPromise = null; }
  }

  // Cold path: (re)boot the iframe. Rebuild only if the product context changed.
  if (_sizeGuideBooted && sizeGuideContextKey(params) !== _sizeGuideBootedKey) {
    _sizeGuideBooted = false;
  }
  const loadToken = ++_sizeGuideModalLoadToken;
  if (loading) { loading.hidden = false; loading.textContent = 'Loading size guide...'; }
  teardownSizeGuideModalAutoHeight();
  iframe.hidden = false;          // make it visible so a deferred prewarm load kicks in
  iframe.style.visibility = 'hidden';
  iframe.style.height = '1px';
  try {
    await ensureSizeGuideBooted(iframe, params);
    if (loadToken !== _sizeGuideModalLoadToken) return;
    revealSizeGuideIframe(iframe, loading);
  } catch (error) {
    console.error('Size guide modal failed:', error);
    teardownSizeGuideModalAutoHeight();
    iframe.onload = null;
    iframe.hidden = true;
    iframe.style.visibility = '';
    iframe.style.height = '';
    _sizeGuideBooted = false; _sizeGuideBootPromise = null;
    if (loading) { loading.hidden = false; loading.textContent = 'Could not load the size guide right now.'; }
  }
};

// Prewarm: boot the guide iframe during idle time (the modal stays hidden) so
// the first open is instant. Only once the product has loaded, so the booted
// context matches what the open will request — otherwise the first open boots.
(function prewarmSizeGuide() {
  const warm = () => {
    const iframe = document.getElementById('size-guide-modal-iframe');
    if (!iframe || _sizeGuideBooted || _sizeGuideBootPromise) return;
    if (!currentProduct?.id) return;
    ensureSizeGuideBooted(iframe, buildSizeGuideParams()).catch(() => {});
  };
  if ('requestIdleCallback' in window) requestIdleCallback(warm, { timeout: 5000 });
  else setTimeout(warm, 2500);
})();


